}

// Spring @Transactional + JTA（跨数据源分布式事务）
@Service
public class OrderXAService {

    @Transactional  // JTA 事务管理器管理 2PC
    public void createOrder(Order order, Payment payment) {
        orderRepo.save(order);   // DB-A
