## 二、Resilience4j 深入

### 2.1 CircuitBreaker 配置

```java
@Configuration
public class ResilienceConfig {

    @Bean
    public CircuitBreakerRegistry circuitBreakerRegistry() {
        var config = CircuitBreakerConfig.custom()
                .failureRateThreshold(50)         // 失败率阈值 50%
                .slowCallRateThreshold(50)        // 慢调用率阈值
                .slowCallDurationThreshold(Duration.ofSeconds(5))
                .minimumNumberOfCalls(10)          // 最少调用次数
                .slidingWindowType(SlidingWindowType.COUNT_BASED)
                .slidingWindowSize(20)             // 窗口大小
                .waitDurationInOpenState(Duration.ofSeconds(30)) // OPEN 持续 30s
                .permittedNumberOfCallsInHalfOpenState(5) // HALF_OPEN 允许5次探测
                .automaticTransitionFromOpenToHalfOpenEnabled(true)
                .recordExceptions(IOException.class, TimeoutException.class)
                .ignoreExceptions(BusinessException.class) // 业务异常不计入失败
                .build();

        return CircuitBreakerRegistry.of(config);
    }

    @Bean
    public CircuitBreaker llmCircuitBreaker(CircuitBreakerRegistry registry) {
        return registry.circuitBreaker("llm-service");
    }
}

@Service
public class LlmService {

    private final CircuitBreaker llmCircuitBreaker;

    // 方式一：装饰器模式
    public String callLlm(String prompt) {
        var decorated = CircuitBreaker.decorateSupplier(llmCircuitBreaker,
                () -> openAiClient.chat(prompt));
        return decorated.get(); // 触发熔断时抛出 CallNotPermittedException
    }

    // 方式二：注解模式
    @CircuitBreaker(name = "llm-service", fallbackMethod = "llmFallback")
    public String callLlmWithAnnotation(String prompt) {
        return openAiClient.chat(prompt);
    }

    public String llmFallback(String prompt, CallNotPermittedException e) {
        return "AI 服务暂时不可用，请稍后重试";
    }

    public String llmFallback(String prompt, TimeoutException e) {
        return "AI 服务响应超时，已简化处理";
    }
}
```

### 2.2 Retry 配置

```java
@Bean
public RetryRegistry retryRegistry() {
    var config = RetryConfig.<String>custom()
            .maxAttempts(3)
            .waitDuration(Duration.ofMillis(500))
            .intervalFunction(IntervalFunction.ofExponentialBackoff(
                    Duration.ofMillis(500), 2.0)) // 500ms, 1000ms, 2000ms
            .retryOnResult(result -> result == null || result.contains("rate_limit"))
            .retryOnException(e -> e instanceof TimeoutException)
            .ignoreExceptions(IllegalArgumentException.class)
            .failAfterMaxAttempts(true)
            .build();

    return RetryRegistry.of(config);
}

// Retry 链式使用
