### 3.3 滑动窗口实现思路

```java
public class SlidingWindowRateLimiter {

    private final int maxRequests;
    private final long windowSizeMs;
    private final int buckets;
    private final long[] bucketTimestamps;
    private final AtomicLongArray bucketCounters;
    private final AtomicLong currentBucket = new AtomicLong(0);

    public SlidingWindowRateLimiter(int maxRequests, Duration window, int buckets) {
        this.maxRequests = maxRequests;
        this.windowSizeMs = window.toMillis();
        this.buckets = buckets;
        this.bucketTimestamps = new long[buckets];
        this.bucketCounters = new AtomicLongArray(buckets);
    }

    public boolean tryAcquire() {
        var now = System.currentTimeMillis();
        advanceBuckets(now);

        // 统计当前窗口内的总请求数
        long total = 0;
        long windowStart = now - windowSizeMs;
        for (int i = 0; i < buckets; i++) {
            if (bucketTimestamps[i] > windowStart) {
                total += bucketCounters.get(i);
            }
        }

        if (total < maxRequests) {
            var bucket = (int) (currentBucket.get() % buckets);
            bucketCounters.incrementAndGet(bucket);
            return true;
        }
        return false;
    }

    private void advanceBuckets(long now) {
        // 计算当前时间对应的桶下标并清理过期桶
        // ...
    }
}
