            .filter(c -> c instanceof TextBlock)
            .map(c -> ((TextBlock) c).text())
            .reduce("", String::concat);

        System.out.println("=== 思考过程 ===\n" + thinking);
        System.out.println("\n=== 最终回答 ===\n" + answer);

        return answer;
