    /**
     * Gemini多模态调用（支持图片+视频+音频）。
     */
    public String analyzeImage(String prompt, Path imagePath) throws Exception {
        var base64 = Base64.getEncoder()
            .encodeToString(Files.readAllBytes(imagePath));
