# 元数据管理与数据治理：从Schema设计到多租户隔离

## 概述

在AI数据工程中，元数据不仅是"关于数据的数据"，它是整个管道的粘合剂，将文档解析、切片、索引、检索、权限控制、版本管理串联为一体。数据治理则确保数据的质量、安全和合规贯穿整个生命周期。本文从Metadata Schema设计出发，覆盖内容指纹去重、ACL权限继承、PII脱敏、删除传播、版本管理、CDC增量更新到多租户隔离的全链路治理方案。

---

## 一、Metadata Schema设计

### 1.1 Schema分层

Metadata Schema分为三层：必需层、业务层、技术层。

```sql
-- PostgreSQL Metadata Schema 完整定义

-- ============ 文档表 ============
CREATE TABLE documents (
    -- 必需字段：任何文档都必须有
    document_id     UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    source_uri      TEXT NOT NULL,                    -- 文件路径/S3 URI/数据库记录
    content_hash    VARCHAR(64) NOT NULL,             -- SHA-256 原始内容哈希
    content_length  BIGINT NOT NULL,                  -- 原始字节数
    mime_type       VARCHAR(127),                     -- MIME类型
    file_name       VARCHAR(512),                     -- 原始文件名

    -- 业务字段：根据实际场景选择性填充
    title           VARCHAR(1024),                    -- 文档标题
    author          VARCHAR(256),                     -- 作者/创建者
    department      VARCHAR(256),                     -- 所属部门
    category        VARCHAR(256),                     -- 分类（如：技术文档/制度/报告）
    tags            TEXT[],                            -- 标签数组
    version         VARCHAR(64) DEFAULT '1.0',        -- 文档版本
    language        VARCHAR(10) DEFAULT 'zh',         -- 语言代码
    access_level    VARCHAR(32) DEFAULT 'internal',   -- public/internal/confidential/secret
    tenant_id       VARCHAR(128) NOT NULL,            -- 多租户隔离
    status          VARCHAR(32) DEFAULT 'active',     -- active/archived/deleted
    expires_at      TIMESTAMPTZ,                      -- 访问有效期（临时文档）

    -- 技术字段：管道的运营数据
    parser_name         VARCHAR(128),                 -- 使用的解析器
    parser_version      VARCHAR(32),                  -- 解析器版本
    parse_duration_ms   BIGINT,                       -- 解析耗时
    parse_error         TEXT,                         -- 解析错误信息

    -- 时间戳
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    ingested_at     TIMESTAMPTZ NOT NULL DEFAULT now() -- 数据入库时间
);

-- ============ 切片表 ============
CREATE TABLE chunks (
    chunk_id        UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    document_id     UUID NOT NULL REFERENCES documents(document_id) ON DELETE CASCADE,
    chunk_index     INT NOT NULL,                     -- 在文档中的序号
    total_chunks    INT NOT NULL,                     -- 文档总chunk数

    -- 内容
    content         TEXT NOT NULL,                    -- 切片文本
    content_hash    VARCHAR(64) NOT NULL,             -- 切片内容SHA-256
    char_count      INT NOT NULL,                     -- 字符数
    token_count     INT NOT NULL,                     -- 估算Token数

    -- 定位信息
    char_start      INT,                              -- 原始文档字符起始位置
    char_end        INT,                              -- 原始文档字符结束位置
    page_number     INT,                              -- PDF页码
    section_path    TEXT,                             -- 章节路径（如"第3章 > 3.2节"）

    -- 切片策略
    chunking_strategy   VARCHAR(128),                 -- fixed_size/paragraph/recursive/semantic/code_aware
    chunk_size_config   INT,                          -- 配置的chunk_size
    overlap_config      INT,                          -- 配置的overlap

    -- Embedding
    embedding_model     VARCHAR(128),                 -- 如 bge-large-zh-v1.5
    embedding_version   VARCHAR(32),                  -- 模型版本
    embedding_dim       INT,                          -- 向量维度
    embedding_status    VARCHAR(32) DEFAULT 'pending',-- pending/embedded/failed

    -- 权限继承
    access_level    VARCHAR(32),                      -- 继承自documents
    tenant_id       VARCHAR(128) NOT NULL,            -- 继承自documents

    -- 状态
    status          VARCHAR(32) DEFAULT 'active',     -- active/outdated/deleted
    previous_chunk_id UUID,                          -- 版本链：更新后的旧chunk引用

    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ============ 向量索引表 (pgvector) ============
CREATE TABLE chunk_embeddings (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    chunk_id        UUID NOT NULL REFERENCES chunks(chunk_id) ON DELETE CASCADE,
    embedding       vector(1024),                     -- 向量字段（维度取决于模型）
    model_name      VARCHAR(128),
    model_version   VARCHAR(32),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- 关键索引
CREATE INDEX idx_documents_tenant ON documents(tenant_id);
CREATE INDEX idx_documents_content_hash ON documents(content_hash);
CREATE INDEX idx_documents_category ON documents(category);
CREATE INDEX idx_documents_status ON documents(status);
CREATE INDEX idx_documents_access_level ON documents(access_level);

CREATE INDEX idx_chunks_document ON chunks(document_id);
CREATE INDEX idx_chunks_tenant ON chunks(tenant_id);
CREATE INDEX idx_chunks_status ON chunks(status);
CREATE INDEX idx_chunks_embedding_status ON chunks(embedding_status);
CREATE INDEX idx_chunks_content_hash ON chunks(content_hash);

-- HNSW索引（向量检索加速）
CREATE INDEX idx_chunk_embeddings_hnsw ON chunk_embeddings
    USING hnsw (embedding vector_cosine_ops)
    WITH (m = 16, ef_construction = 200);
