### 2.2 MinHash算法

MinHash适用于长文本去重，基于Jaccard相似度。

```java
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.PriorityQueue;

public class MinHashService {

    private final int numHashes;      // 哈希函数数量，典型值128-256
    private final long[] hashSeeds;   // 随机种子

    public MinHashService(int numHashes) {
        this.numHashes = numHashes;
        this.hashSeeds = new long[numHashes];
        var random = new java.util.Random(42); // 固定种子确保一致性
        for (int i = 0; i < numHashes; i++) {
            hashSeeds[i] = random.nextLong();
        }
    }

    /**
     * 计算文档的MinHash签名
     */
    public long[] computeMinHash(String text) {
        var tokens = tokenize(text); // 返回shingle集合

        var signature = new long[numHashes];
        for (int i = 0; i < numHashes; i++) {
            long minHash = Long.MAX_VALUE;
            for (var token : tokens) {
                var hash = murmurHash64(token, hashSeeds[i]);
                if (hash < minHash) {
                    minHash = hash;
                }
            }
            signature[i] = minHash;
        }

        return signature;
    }

    /**
     * Jaccard相似度估计 = 签名中匹配的比例
     */
    public double estimateJaccard(long[] sig1, long[] sig2) {
        int matches = 0;
        for (int i = 0; i < sig1.length; i++) {
            if (sig1[i] == sig2[i]) {
                matches++;
            }
        }
        return (double) matches / sig1.length;
    }

    /**
     * LSH分桶：将签名分为b个band，每个band有r行
     * 如果两个文档的任意一个band完全匹配，则认为是候选重复
     */
    public record BandKey(int bandIndex, int bandHash) {}

    public List<BandKey> computeBandKeys(long[] signature, int bands) {
        var rowsPerBand = signature.length / bands;
        var keys = new ArrayList<BandKey>();

        for (int b = 0; b < bands; b++) {
            var bandHash = 0;
            for (int r = 0; r < rowsPerBand; r++) {
                bandHash = 31 * bandHash + Long.hashCode(signature[b * rowsPerBand + r]);
            }
            keys.add(new BandKey(b, bandHash));
        }

        return keys;
    }

    private List<String> tokenize(String text) {
        // 生成 word-shingles（3-5个词一组）
        var words = text.split("\\s+");
        var shingles = new HashSet<String>();
        for (int i = 0; i < words.length - 2; i++) {
            shingles.add(String.join(" ",
                java.util.Arrays.copyOfRange(words, i, Math.min(i + 3, words.length))
            ));
        }
        return new ArrayList<>(shingles);
    }

    private long murmurHash64(String data, long seed) {
        // MurmurHash 64-bit 实现（简化版）
        var bytes = data.getBytes(java.nio.charset.StandardCharsets.UTF_8);
        long h = seed ^ (bytes.length * 0xc6a4a7935bd1e995L);

        for (int i = 0; i < bytes.length; i += 8) {
            long k = 0;
            for (int j = 0; j < 8 && (i + j) < bytes.length; j++) {
                k |= ((long) (bytes[i + j] & 0xFF)) << (j * 8);
            }
            k *= 0xc6a4a7935bd1e995L;
            k = Long.rotateRight(k, 47);
            k *= 0xc6a4a7935bd1e995L;
            h ^= k;
            h = Long.rotateRight(h, 47);
            h = h * 5 + 0x52dce729;
        }

        h ^= h >>> 33;
        h *= 0xff51afd7ed558ccdL;
        h ^= h >>> 33;
        h *= 0xc4ceb9fe1a85ec53L;
        h ^= h >>> 33;

        return h;
    }
}
```

### 2.3 实际去重流程

```java
import javax.sql.DataSource;
import java.sql.*;
import java.math.BigInteger;

public class DeduplicationService {

    private final SimHashService simHashService;
    private final DataSource dataSource;

    public DeduplicationService(SimHashService simHashService, DataSource dataSource) {
        this.simHashService = simHashService;
        this.dataSource = dataSource;
    }

    /**
     * 新文档入库的完整去重流程
     * @return 如果文档是重复的，返回已存在的document_id；否则返回null
     */
    public record DedupResult(boolean isDuplicate, String existingDocumentId) {}

    public DedupResult checkAndDedup(String documentContent, String documentId) {
        var simHash = simHashService.computeSimHash(documentContent);

        // 1. 精确哈希匹配（SHA-256）— O(1)
        var contentHash = sha256(documentContent);
        if (existsByContentHash(contentHash)) {
            var existingId = getDocumentIdByHash(contentHash);
            return new DedupResult(true, existingId);
        }

        // 2. SimHash模糊匹配 — 查询分段索引
        var segmentKeys = simHashService.computeSegmentKeys(simHash, 4);
        var candidates = queryBySegmentKeys(segmentKeys);

        for (var candidate : candidates) {
            var distance = simHashService.hammingDistance(
                simHash, new BigInteger(candidate.simHash, 16)
            );
            if (distance <= 3) {
                return new DedupResult(true, candidate.documentId);
            }
        }

        // 3. 不是重复文档，存储SimHash和分段索引
        storeSimHash(documentId, simHash, segmentKeys, contentHash);
        return new DedupResult(false, null);
    }

    private String sha256(String content) {
        try {
            var md = java.security.MessageDigest.getInstance("SHA-256");
            var digest = md.digest(content.getBytes(java.nio.charset.StandardCharsets.UTF_8));
            return javax.xml.bind.DatatypeConverter.printHexBinary(digest);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    private boolean existsByContentHash(String hash) {
        try (var conn = dataSource.getConnection();
             var stmt = conn.prepareStatement(
                 "SELECT 1 FROM document_fingerprints WHERE content_hash = ?")) {
            stmt.setString(1, hash);
            try (var rs = stmt.executeQuery()) {
                return rs.next();
            }
        } catch (SQLException e) {
            throw new RuntimeException(e);
        }
    }

    private String getDocumentIdByHash(String hash) {
        try (var conn = dataSource.getConnection();
             var stmt = conn.prepareStatement(
                 "SELECT document_id FROM document_fingerprints WHERE content_hash = ?")) {
            stmt.setString(1, hash);
            try (var rs = stmt.executeQuery()) {
                return rs.next() ? rs.getString("document_id") : null;
            }
        } catch (SQLException e) {
            throw new RuntimeException(e);
        }
    }

    private record CandidateDoc(String documentId, String simHash) {}

    private List<CandidateDoc> queryBySegmentKeys(List<SimHashService.SegmentKey> keys) {
        var results = new ArrayList<CandidateDoc>();
        try (var conn = dataSource.getConnection();
             var stmt = conn.prepareStatement(
                 "SELECT DISTINCT d.document_id, d.simhash FROM document_fingerprints d " +
                 "JOIN simhash_segments s ON d.document_id = s.document_id " +
                 "WHERE s.segment_index = ? AND s.segment_value = ?")) {

            for (var key : keys) {
                stmt.setInt(1, key.segmentIndex());
                stmt.setInt(2, key.segmentValue());
                try (var rs = stmt.executeQuery()) {
                    while (rs.next()) {
                        results.add(new CandidateDoc(
                            rs.getString("document_id"),
                            rs.getString("simhash")
                        ));
                    }
                }
            }
        } catch (SQLException e) {
            throw new RuntimeException(e);
        }
        return results;
    }

    private void storeSimHash(String documentId, BigInteger simHash,
                               List<SimHashService.SegmentKey> segments, String contentHash) {
        try (var conn = dataSource.getConnection()) {
            conn.setAutoCommit(false);
            try {
                // 主表
                try (var stmt = conn.prepareStatement(
                    "INSERT INTO document_fingerprints (document_id, simhash, content_hash) VALUES (?, ?, ?)")) {
                    stmt.setString(1, documentId);
                    stmt.setString(2, simHash.toString(16));
                    stmt.setString(3, contentHash);
                    stmt.executeUpdate();
                }
                // 分段索引
                try (var stmt = conn.prepareStatement(
                    "INSERT INTO simhash_segments (document_id, segment_index, segment_value) VALUES (?, ?, ?)")) {
                    for (var seg : segments) {
                        stmt.setString(1, documentId);
                        stmt.setInt(2, seg.segmentIndex());
                        stmt.setInt(3, seg.segmentValue());
                        stmt.addBatch();
                    }
                    stmt.executeBatch();
                }
                conn.commit();
            } catch (SQLException e) {
                conn.rollback();
                throw e;
            }
        } catch (SQLException e) {
            throw new RuntimeException(e);
        }
    }
}
