### 3.2 检索时权限过滤

```java
/**
 * 权限感知的向量检索 — 在SQL层面过滤无权访问的文档
 */
public class AclAwareRetrievalService {

    private final DataSource dataSource;

    /**
     * 带ACL过滤的向量相似度检索
     * @param embedding 查询向量
     * @param userAccessLevels 用户有权访问的access_level列表
     * @param topK 返回结果数量
     */
    public record AclSearchResult(String chunkId, String content,
                                   double similarity, String accessLevel) {}

    public List<AclSearchResult> searchWithAcl(
            float[] embedding, List<String> userAccessLevels, int topK) {

        // 将access_level列表转为SQL IN子句参数
        var placeholders = userAccessLevels.stream()
            .map(l -> "?").collect(java.util.stream.Collectors.joining(","));

        var sql = """
            SELECT c.chunk_id, c.content,
                   1 - (e.embedding <=> ?::vector) AS similarity,
                   c.access_level
            FROM chunk_embeddings e
            JOIN chunks c ON e.chunk_id = c.chunk_id
            WHERE c.access_level IN (%s)
              AND c.status = 'active'
            ORDER BY e.embedding <=> ?::vector
            LIMIT ?
            """.formatted(placeholders);

        try (var conn = dataSource.getConnection();
             var stmt = conn.prepareStatement(sql)) {

            // 设置查询向量（第一个和倒数第二个参数）
            var vectorStr = "[" + java.util.Arrays.stream(embedding)
                .mapToObj(f -> String.format("%.6f", f))
                .collect(java.util.stream.Collectors.joining(",")) + "]";
            stmt.setString(1, vectorStr);

            // 设置access_level过滤值
            int paramIndex = 2;
            for (var level : userAccessLevels) {
                stmt.setString(paramIndex++, level);
            }

            // 设置查询向量（用于排序）
            stmt.setString(paramIndex++, vectorStr);
            stmt.setInt(paramIndex, topK);

            var results = new ArrayList<AclSearchResult>();
            try (var rs = stmt.executeQuery()) {
                while (rs.next()) {
                    results.add(new AclSearchResult(
                        rs.getString("chunk_id"),
                        rs.getString("content"),
                        rs.getDouble("similarity"),
                        rs.getString("access_level")
                    ));
                }
            }
            return results;

        } catch (SQLException e) {
            throw new RuntimeException(e);
        }
    }
}
```

### 3.3 OPA (Open Policy Agent) 集成

```java
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;

/**
 * OPA集成 — 将权限决策委托给OPA策略引擎
 */
public class OpaPolicyService {

    private final HttpClient client = HttpClient.newHttpClient();
    private final String opaUrl; // http://localhost:8181

    public OpaPolicyService(String opaUrl) {
        this.opaUrl = opaUrl;
    }

    /**
     * 查询用户是否有权限访问指定文档
     */
    public boolean canAccess(String userId, String documentId, String action) {
        var input = """
            {
                "input": {
                    "user_id": "%s",
                    "document_id": "%s",
                    "action": "%s"
                }
            }
            """.formatted(userId, documentId, action);

        try {
            var request = HttpRequest.newBuilder()
                .uri(URI.create(opaUrl + "/v1/data/rag/access/allow"))
                .header("Content-Type", "application/json")
                .POST(HttpRequest.BodyPublishers.ofString(input))
                .build();

            var response = client.send(request, HttpResponse.BodyHandlers.ofString());
            // OPA返回 {"result": true/false}
            var mapper = new com.fasterxml.jackson.databind.ObjectMapper();
            var root = mapper.readTree(response.body());
            return root.path("result").asBoolean(false);

        } catch (Exception e) {
            // 无法连接OPA时的默认策略：拒绝访问（安全优先）
            return false;
        }
    }
}
