     * 完整的PII检测与脱敏
     */
    public String mask(String text, MaskingStrategy strategy) {
        var masked = text;

        // 1. 正则模式脱敏（高置信度，直接替换）
        var regexMatches = regexDetector.detect(text);
        for (int i = regexMatches.size() - 1; i >= 0; i--) {
            var m = regexMatches.get(i);
            masked = masked.substring(0, m.start()) + m.maskedValue() + masked.substring(m.end());
        }

        // 2. NER脱敏（人名/地名/机构名）
        // 根据策略选择脱敏方式
        // 实现略...

        return masked;
    }

