## 七、增量更新：CDC (Change Data Capture)

使用Debezium监听数据库变更，触发解析-切片-索引管道：

```java
import org.springframework.stereotype.Service;
import org.springframework.context.event.EventListener;

@Service
public class CdcChangeHandler {

    private final DocumentParserService parserService;
    private final ChunkingService chunkingService;
    private final EmbeddingService embeddingService;

    /**
     * 监听数据库变更事件（由Debezium通过Kafka推送）
     */
    public record CdcEvent(
        String operation,    // "c"(create), "u"(update), "d"(delete), "r"(read/snapshot)
        String table,
        String documentId,
        java.util.Map<String, Object> before,
        java.util.Map<String, Object> after,
        long timestamp
    ) {}

    public void handleCdcEvent(CdcEvent event) {
        switch (event.operation()) {
            case "c" -> {
                // 新文档：完整管道
                var pipeline = new DocumentPipeline(
                    parserService, chunkingService, embeddingService
                );
                pipeline.process(event.documentId());
            }
            case "u" -> {
                // 更新文档：只处理变化的字段
                if (contentChanged(event.before(), event.after())) {
                    var versionService = new VersionManagementService(null);
                    // versionService.updateDocument(...);
                }
                if (aclChanged(event.before(), event.after())) {
                    var aclPropagator = new AclPropagator(null);
                    aclPropagator.propagateDocumentAcl(event.documentId());
                }
            }
            case "d" -> {
                // 删除文档：级联清理
                var deleteService = new CascadeDeleteService(null);
                deleteService.deleteDocument(event.documentId());
            }
        }
    }

    private boolean contentChanged(java.util.Map<String, Object> before,
                                    java.util.Map<String, Object> after) {
        return !java.util.Objects.equals(
            before.get("content_hash"), after.get("content_hash")
        );
    }

    private boolean aclChanged(java.util.Map<String, Object> before,
                                java.util.Map<String, Object> after) {
        return !java.util.Objects.equals(
            before.get("access_level"), after.get("access_level")
        );
    }
}
