    public static final ScopedValue<String> USER_ID = ScopedValue.newInstance();

    /**
     * 在租户上下文中执行操作
     */
    public static <T> T withTenant(String tenantId, java.util.function.Supplier<T> action) {
        return ScopedValue.where(TENANT_ID, tenantId).call(action::get);
    }

    /**
     * 通过HikariCP连接池代理设置租户上下文
     */
    public static class TenantAwareDataSource implements javax.sql.DataSource {
        private final javax.sql.DataSource delegate;

        public TenantAwareDataSource(javax.sql.DataSource delegate) {
            this.delegate = delegate;
        }

        @Override
        public java.sql.Connection getConnection() throws java.sql.SQLException {
            var conn = delegate.getConnection();
            var tenantId = TENANT_ID.orElse("default");
            try (var stmt = conn.createStatement()) {
                stmt.execute("SET app.current_tenant_id = '" + tenantId + "'");
            }
            return conn;
        }

        @Override
        public java.sql.Connection getConnection(String username, String password)
                throws java.sql.SQLException {
            var conn = delegate.getConnection(username, password);
            var tenantId = TENANT_ID.orElse("default");
            try (var stmt = conn.createStatement()) {
                stmt.execute("SET app.current_tenant_id = '" + tenantId + "'");
            }
            return conn;
        }

