        PENDING, EMBEDDING, EMBEDDED, INDEXED, FAILED
    }

    public ChunkItem withEmbedding(float[] embedding) {
        return new ChunkItem(
            chunkId, chunkIndex, content, tokenCount, embedding, sectionPath, ChunkStatus.EMBEDDED
        );
    }
}
