@Component
public class OnlineMetricsCollector {

    private final MeterRegistry registry;

    public OnlineMetricsCollector(MeterRegistry registry) {
        this.registry = registry;
    }

    public void recordUserFeedback(String conversationId, boolean liked,
                                    String modelName, String promptVersion) {
        var tags = Tags.of("model", modelName, "prompt_version", promptVersion);
        registry.counter("ai.feedback.total", tags).increment();
        if (liked) {
            registry.counter("ai.feedback.like", tags).increment();
        } else {
            registry.counter("ai.feedback.dislike", tags).increment();
        }
    }

    public void recordLatency(String modelName, long latencyMs) {
        Timer.builder("ai.latency")
            .tag("model", modelName)
            .publishPercentiles(0.5, 0.95, 0.99)
            .publishPercentileHistogram()
            .register(registry)
            .record(latencyMs, TimeUnit.MILLISECONDS);
    }

    public void recordTokenUsage(String modelName, int promptTokens,
                                  int completionTokens, double cost) {
        var tags = Tags.of("model", modelName);
        registry.counter("ai.tokens.prompt", tags).increment(promptTokens);
        registry.counter("ai.tokens.completion", tags).increment(completionTokens);
        registry.counter("ai.cost", tags).increment(cost);
    }

    public void recordTaskCompletion(String conversationId, boolean completed,
                                      boolean escalated) {
        var tags = Tags.of("conversation_id", conversationId);
        registry.counter("ai.task.total", tags).increment();
        if (completed) registry.counter("ai.task.completed", tags).increment();
        if (escalated) registry.counter("ai.task.escalated", tags).increment();
    }
}
