## 五、AI 可观测性技术栈

### 5.1 OpenTelemetry 集成

使用 OpenTelemetry Java Agent 自动采集，结合自定义 Span 实现 AI 专用链路追踪。

```java
/**
 * AI 追踪门面接口。统一定义 AI 调用的 Span 结构。
 */
public interface AiTracePort {

    /**
     * 创建一个 AI 调用 Span。
     */
    Span startAiSpan(String operationType, Map<String, String> attributes);

    /**
     * 记录 LLM 调用事件（包含 Token 和成本信息）
     */
    void recordLlmEvent(Span span, String model, int promptTokens,
                         int completionTokens, double cost, long latencyMs);

    /**
     * 记录工具调用事件
     */
    void recordToolCall(Span span, String toolName,
                         Map<String, Object> parameters, Object result, long latencyMs);

    /**
     * 记录 RAG 检索事件
     */
    void recordRetrieval(Span span, String query, List<String> retrievedDocIds,
                          int topK, long latencyMs);

    /**
     * 记录用户反馈事件
     */
    void recordUserFeedback(String traceId, String userId,
                             boolean liked, String comment);
}

/**
 * OpenTelemetry 实现
 */
@Component
public class OpenTelemetryAiTrace implements AiTracePort {

    private final Tracer tracer;

    public OpenTelemetryAiTrace(OpenTelemetry openTelemetry) {
        this.tracer = openTelemetry.getTracer("ai-application", "1.0.0");
    }

    @Override
    public Span startAiSpan(String operationType, Map<String, String> attributes) {
        var spanBuilder = tracer.spanBuilder("ai." + operationType)
            .setSpanKind(SpanKind.INTERNAL);

        attributes.forEach(spanBuilder::setAttribute);
        return spanBuilder.startSpan();
    }

    @Override
    public void recordLlmEvent(Span span, String model, int promptTokens,
                                int completionTokens, double cost, long latencyMs) {
        span.setAttribute("llm.model", model);
        span.setAttribute("llm.prompt_tokens", promptTokens);
        span.setAttribute("llm.completion_tokens", completionTokens);
        span.setAttribute("llm.total_tokens", promptTokens + completionTokens);
        span.setAttribute("llm.cost", cost);
        span.setAttribute("llm.latency_ms", latencyMs);

        // 添加事件
        span.addEvent("llm.call.completed",
            Attributes.of(
                AttributeKey.stringKey("model"), model,
                AttributeKey.longKey("prompt_tokens"), promptTokens,
                AttributeKey.longKey("completion_tokens"), completionTokens,
                AttributeKey.doubleKey("cost"), cost
            ));
    }

    @Override
    public void recordRetrieval(Span span, String query,
                                 List<String> retrievedDocIds,
                                 int topK, long latencyMs) {
        span.setAttribute("retrieval.top_k", topK);
        span.setAttribute("retrieval.result_count", retrievedDocIds.size());
        span.setAttribute("retrieval.latency_ms", latencyMs);

        span.addEvent("retrieval.completed",
            Attributes.of(
                AttributeKey.stringKey("query_preview"),
                    query.length() > 100 ? query.substring(0, 100) : query,
                AttributeKey.longKey("result_count"), retrievedDocIds.size(),
                AttributeKey.longKey("latency_ms"), latencyMs
            ));
    }

    @Override
    public void recordToolCall(Span span, String toolName,
                                Map<String, Object> parameters,
                                Object result, long latencyMs) {
        span.setAttribute("tool.name", toolName);
        span.setAttribute("tool.latency_ms", latencyMs);
        span.setAttribute("tool.success", result != null);

        span.addEvent("tool.call.completed",
            Attributes.of(
                AttributeKey.stringKey("tool_name"), toolName,
                AttributeKey.longKey("latency_ms"), latencyMs
            ));
    }

    @Override
    public void recordUserFeedback(String traceId, String userId,
                                    boolean liked, String comment) {
        var span = tracer.spanBuilder("ai.user_feedback")
            .setAttribute("trace.id", traceId)
            .setAttribute("user.id", userId)
            .setAttribute("feedback.liked", liked)
            .startSpan();

        if (comment != null && !comment.isEmpty()) {
            span.setAttribute("feedback.comment", comment);
        }
        span.end();
    }
}
```

### 5.2 请求拦截器实现自动追踪

```java
/**
 * 通过 Spring AI 的 Advisor 机制自动为每次 LLM 调用添加追踪。
 */
@Component
public class AiTracingAdvisor implements RequestResponseAdvisor {

    private final AiTracePort aiTrace;
    private final MeterRegistry meterRegistry;

    @Override
    public AdvisedRequest adviseRequest(AdvisedRequest request,
                                         Map<String, Object> context) {
        var span = aiTrace.startAiSpan("llm_call", Map.of(
            "model", request.model() != null ? request.model() : "unknown"
        ));
        context.put("ai.span", span);
        context.put("ai.start_time", System.currentTimeMillis());
        return request;
    }

    @Override
    public ChatResponse adviseResponse(ChatResponse response,
                                        Map<String, Object> context) {
        var span = (Span) context.get("ai.span");
        var startTime = (Long) context.get("ai.start_time");
        if (span != null && startTime != null) {
            var latency = System.currentTimeMillis() - startTime;
            var metadata = response.getMetadata();
            var usage = metadata.getUsage();

            // 记录 LLM 调用事件
            aiTrace.recordLlmEvent(span,
                metadata.getModel(),
                usage != null ? (int) usage.getPromptTokens() : 0,
                usage != null ? (int) usage.getGenerationTokens() : 0,
                calculateCost(metadata.getModel(), usage),
                latency
            );

            // 记录 Micrometer 指标
            meterRegistry.timer("ai.llm.call",
                "model", metadata.getModel())
                .record(latency, TimeUnit.MILLISECONDS);

            span.end();
        }
        return response;
    }

    private double calculateCost(String model, Usage usage) {
        if (usage == null) return 0;
        // 简化的成本计算
        var costPer1kPrompt = switch (model) {
            case "gpt-4o" -> 0.0025;
            case "gpt-4o-mini" -> 0.00015;
            case "claude-sonnet-4-20250514" -> 0.003;
            default -> 0.001;
        };
        var costPer1kCompletion = costPer1kPrompt * 4;  // 通常 completion 是 prompt 的 4 倍
        return (usage.getPromptTokens() * costPer1kPrompt
            + usage.getGenerationTokens() * costPer1kCompletion) / 1000.0;
    }
}
