### 5.4 Langfuse vs OpenTelemetry 对比

```java
/**
 * Langfuse 是专为 LLM 应用设计的可观测性平台，提供开箱即用的：
 * - Prompt 版本追踪
 * - Token 用量和成本分析
 * - LLM 调用链可视化
 * - 用户反馈收集
 * - 评估打分集成
 *
 * OpenTelemetry 是通用可观测性标准，优势在于：
 * - 厂商无关，可以和任意后端（Jaeger, Tempo, Datadog）集成
 * - 与现有的微服务追踪体系统一
 * - 生态丰富，Java Agent 零代码自动采集
 *
 * 推荐策略：OpenTelemetry 作为基础设施层（统一采集），
 * Langfuse 作为 AI 专用的业务分析层（导出 OTLP 数据到 Langfuse）。
 */

/**
 * 双写适配器：同时向 OpenTelemetry 和 Langfuse 发送追踪数据。
 */
@Component
public class DualTraceAdapter implements AiTracePort {

    private final AiTracePort otelTrace;
    private final LangfuseClient langfuse;

    @Override
    public Span startAiSpan(String operationType, Map<String, String> attributes) {
        var otelSpan = otelTrace.startAiSpan(operationType, attributes);

        // 同步创建 Langfuse Trace
        var langfuseTrace = langfuse.trace()
            .name(operationType)
            .metadata(attributes)
            .create();

        // 将 Langfuse trace ID 记录到 OTEL Span
        otelSpan.setAttribute("langfuse.trace_id", langfuseTrace.getId());
        return otelSpan;
    }

    @Override
    public void recordLlmEvent(Span span, String model, int promptTokens,
                                int completionTokens, double cost, long latencyMs) {
        otelTrace.recordLlmEvent(span, model, promptTokens,
            completionTokens, cost, latencyMs);

        // 同步上报 Langfuse
        var traceId = span.getSpanContext().getTraceId();
        langfuse.generation()
            .traceId(traceId)
            .model(model)
            .usage(new LangfuseUsage(promptTokens, completionTokens))
            .cost(cost)
            .latency(latencyMs)
            .create();
    }

    // 其他方法类似双写...
}
