### 2. Insecure Output Handling（不安全输出处理）— LLM02

LLM生成的输出可能包含恶意脚本、有害内容或不安全的格式化数据。如果输出直接插入HTML页面、当作命令执行或存入数据库，会造成严重后果。

**防御策略：**

```java
// OutputSecurityFilter.java — 输出安全过滤器
package com.ai.security.output;

import java.util.regex.Pattern;
import java.util.Set;
import java.util.stream.Collectors;

public class OutputSecurityFilter {

    // HTML特殊字符实体编码
    private static final java.util.Map<Character, String> HTML_ENTITIES = java.util.Map.of(
        '<', "&lt;",
        '>', "&gt;",
        '"', "&quot;",
        '\'', "&#x27;",
        '&', "&amp;",
        '/', "&#x2F;"
    );

    // 敏感内容关键词
    private final Set<String> blockedContentPatterns;

    // JS代码检测
    private static final Pattern SCRIPT_TAG = Pattern.compile(
        "<script[^>]*>[\\s\\S]*?</script>", Pattern.CASE_INSENSITIVE
    );
    private static final Pattern JS_EVENT = Pattern.compile(
        "on\\w+\\s*=", Pattern.CASE_INSENSITIVE
    );
    private static final Pattern JS_PROTOCOL = Pattern.compile(
        "javascript\\s*:", Pattern.CASE_INSENSITIVE
    );

    public OutputSecurityFilter(Set<String> blockedPatterns) {
        this.blockedContentPatterns = blockedPatterns.stream()
            .map(String::toLowerCase)
            .collect(Collectors.toSet());
    }

    /**
     * HTML实体编码
     */
    public String htmlEncode(String input) {
        if (input == null) return null;
        var sb = new StringBuilder(input.length());
        for (var i = 0; i < input.length(); i++) {
            var c = input.charAt(i);
            var escaped = HTML_ENTITIES.get(c);
            sb.append(escaped != null ? escaped : c);
        }
        return sb.toString();
    }

    /**
     * 完整输出安全审核
     */
    public OutputAuditResult audit(String llmOutput) {
        var issues = new java.util.ArrayList<String>();
        var riskLevel = "safe";

        // 1. XSS检测
        if (SCRIPT_TAG.matcher(llmOutput).find()) {
            issues.add("XSS: Script tag detected");
            riskLevel = "critical";
        }
        if (JS_EVENT.matcher(llmOutput).find()) {
            issues.add("XSS: JavaScript event handler detected");
            riskLevel = "critical";
        }
        if (JS_PROTOCOL.matcher(llmOutput).find()) {
            issues.add("XSS: javascript: protocol detected");
            riskLevel = "critical";
        }

        // 2. 敏感内容检测
        var lowerOutput = llmOutput.toLowerCase();
        for (var pattern : blockedContentPatterns) {
            if (lowerOutput.contains(pattern)) {
                issues.add("Blocked content pattern: " + pattern);
                riskLevel = riskLevel.equals("critical") ? "critical" : "high";
            }
        }

        // 3. 净化输出（如果存在XSS问题）
        var sanitized = riskLevel.equals("critical")
            ? sanitizeHtml(llmOutput)
            : llmOutput;

        return new OutputAuditResult(
            sanitized,
            riskLevel.equals("safe"),
            riskLevel,
            issues
        );
    }

    /**
     * HTML净化 — 移除所有script/事件监听/javascript协议
     */
    public String sanitizeHtml(String html) {
        if (html == null) return null;
        var result = SCRIPT_TAG.matcher(html).replaceAll("");
        result = JS_EVENT.matcher(result).replaceAll("data-removed=");
        result = JS_PROTOCOL.matcher(result).replaceAll("blocked:");
        return result;
    }

    /**
     * Markdown输出安全 — 防止Markdown中嵌入HTML XSS
     */
    public String sanitizeMarkdown(String markdown) {
        if (markdown == null) return null;
        // 对Markdown中的HTML块进行净化
        var result = markdown.replaceAll(
            "(?s)<script[^>]*>.*?</script>", "[SCRIPT BLOCKED]"
        );
        result = result.replaceAll(
            "\\[([^]]*)\\]\\(javascript:", "[$1](blocked:"
        );
        return result;
    }

    public record OutputAuditResult(
        String sanitizedOutput,
        boolean isSafe,
        String riskLevel,
        java.util.List<String> issues
    ) {
        public boolean canReturn() {
            return isSafe || riskLevel.equals("low");
        }
    }
}
```

