### 3. Training Data Poisoning（训练数据投毒）— LLM03

在RAG（检索增强生成）场景中，攻击者通过上传恶意文档来污染知识库，使模型在回答相关问题时输出攻击者预设的内容。防御需要在数据进入知识库之前建立多层审核管道。

```java
// DocumentUploadSecurityAudit.java — 文档上传安全审核
package com.ai.security.poisoning;

import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.*;
import java.util.concurrent.*;

public class DocumentUploadSecurityAudit {

    // 已知恶意文档哈希黑名单
    private final Set<String> knownMaliciousHashes;
    // 内容审核规则
    private final List<ContentAuditRule> auditRules;
    // 上传频率追踪（防止批量投毒）
    private final ConcurrentHashMap<String, UploadWindow> uploadWindows;

    public DocumentUploadSecurityAudit() {
        this.knownMaliciousHashes = ConcurrentHashMap.newKeySet();
        this.auditRules = loadDefaultRules();
        this.uploadWindows = new ConcurrentHashMap<>();
    }

    /**
     * 完整文档审核管道
     */
    public AuditResult auditDocument(DocumentUpload upload) {
        var findings = new ArrayList<String>();
        var passed = true;

        // 阶段1：来源验证
        var sourceCheck = verifySource(upload);
        if (!sourceCheck.passed()) {
            findings.addAll(sourceCheck.findings());
            passed = false;
        }

        // 阶段2：哈希校验
        var hash = computeSha256(upload.content());
        if (knownMaliciousHashes.contains(hash)) {
            findings.add("Document hash matches known malicious content");
            passed = false;
        }

        // 阶段3：大小限制
        if (upload.content().length() > 50 * 1024 * 1024) { // 50MB
            findings.add("Document exceeds maximum size (50MB)");
            passed = false;
        }

        // 阶段4：文件类型校验（不仅依赖扩展名，检查Magic Bytes）
        var realType = detectRealType(upload.content());
        if (!upload.declaredType().equalsIgnoreCase(realType)) {
            findings.add("File type mismatch: declared=" + upload.declaredType()
                + ", actual=" + realType);
            passed = false;
        }

        // 阶段5：内容审核规则
        for (var rule : auditRules) {
            var result = rule.evaluate(upload.content());
            if (!result.passed()) {
                findings.add(result.reason());
                passed = false;
            }
        }

        // 阶段6：上传频率检测
        var uploaderId = upload.uploaderId();
        var window = uploadWindows.compute(uploaderId, (k, v) ->
            v == null ? new UploadWindow() : v
        );
        window.record();
        if (window.isRateLimited(100, 60)) { // 60秒内100次
            findings.add("Rate limit exceeded for uploader: " + uploaderId);
            passed = false;
        }

        return new AuditResult(passed, hash, findings);
    }

    private SourceVerifyResult verifySource(DocumentUpload upload) {
        // 验证上传者身份、权限等
        var findings = new ArrayList<String>();
        if (upload.uploaderId() == null || upload.uploaderId().isBlank()) {
            findings.add("Anonymous upload not permitted");
        }
        return new SourceVerifyResult(
            findings.isEmpty(),
            findings
        );
    }

    private String computeSha256(byte[] content) {
        try {
            var md = MessageDigest.getInstance("SHA-256");
            var digest = md.digest(content);
            return Base64.getEncoder().encodeToString(digest);
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("SHA-256 not available", e);
        }
    }

    private String detectRealType(byte[] content) {
        if (content.length < 4) return "unknown";
        // Magic Bytes检测
        if (content[0] == (byte) 0xFF && content[1] == (byte) 0xD8) return "jpeg";
        if (content[0] == (byte) 0x89 && content[1] == (byte) 0x50
            && content[2] == (byte) 0x4E && content[3] == (byte) 0x47) return "png";
        if (content[0] == (byte) 0x25 && content[1] == (byte) 0x50
            && content[2] == (byte) 0x44 && content[3] == (byte) 0x46) return "pdf";
        if (content[0] == (byte) 0x50 && content[1] == (byte) 0x4B) return "zip";
        return "unknown";
    }

    private List<ContentAuditRule> loadDefaultRules() {
        return List.of(
            // 规则：检测隐藏的系统指令
            new ContentAuditRule("hidden-instruction",
                content -> {
                    var text = new String(content).toLowerCase();
                    var suspicious = text.contains("[system]")
                        || text.contains("忽略所有指令")
                        || text.contains("ignore all instructions");
                    return new RuleResult(!suspicious,
                        suspicious ? "Detected hidden system instructions" : "OK");
                }
            ),
            // 规则：检测Prompt注入标记
            new ContentAuditRule("injection-marker",
                content -> {
                    var text = new String(content);
                    var hasMarkers = text.contains("<<<") && text.contains(">>>");
                    return new RuleResult(!hasMarkers,
                        hasMarkers ? "Detected injection delimiters" : "OK");
                }
            ),
            // 规则：最小内容长度
            new ContentAuditRule("min-length",
                content -> new RuleResult(
                    content.length >= 100 || new String(content).trim().length() >= 50,
                    "Document content too short, possibly placeholder for injection"
                )
            )
        );
    }

    // 内部类型定义
    public record DocumentUpload(
        String uploaderId,
        byte[] content,
        String declaredType,
        String fileName
    ) {}

    public record SourceVerifyResult(boolean passed, List<String> findings) {}
    public record RuleResult(boolean passed, String reason) {}
    public record AuditResult(boolean passed, String hash, List<String> findings) {
        public boolean isSafeForIngestion() {
            return passed;
        }
    }

    @FunctionalInterface
    public interface ContentRule {
        RuleResult evaluate(byte[] content);
    }

    public record ContentAuditRule(String name, ContentRule rule) {
        public RuleResult evaluate(byte[] content) {
            return rule.evaluate(content);
        }
    }

    static class UploadWindow {
        private final java.util.Deque<Long> timestamps = new java.util.ArrayDeque<>();
        synchronized void record() {
            timestamps.addLast(System.currentTimeMillis());
        }
        synchronized boolean isRateLimited(int maxRequests, int windowSeconds) {
            var cutoff = System.currentTimeMillis() - (windowSeconds * 1000L);
            while (!timestamps.isEmpty() && timestamps.peekFirst() < cutoff) {
                timestamps.pollFirst();
            }
            return timestamps.size() > maxRequests;
        }
    }
}
