### 4. Model Denial of Service（模型拒绝服务）— LLM04

LLM推理成本高昂，攻击者可能通过发送超大输入、无限循环请求或递归Tool调用来耗尽资源。需要多层限流和资源控制。

```java
// MultiLayerRateLimiter.java — 多层限流实现
package com.ai.security.rate;

import java.time.Duration;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;

/**
 * 使用JDK内置工具实现令牌桶限流，无需外部依赖
 * 三层防护：全局限流 -> 用户级限流 -> Token预算硬限制
 */
public class MultiLayerRateLimiter {

    // === 第一层：全局令牌桶 ===
    private final TokenBucket globalBucket;

    // === 第二层：每用户令牌桶 ===
    private final ConcurrentHashMap<String, TokenBucket> userBuckets;

    // === 第三层：并发控制 ===
    private final Semaphore concurrentSemaphore;

    // === 配置 ===
    private final long maxInputTokens;
    private final long maxOutputTokens;

    public MultiLayerRateLimiter(
        long globalTokensPerSecond,
        int maxConcurrentRequests,
        long maxInputTokens,
        long maxOutputTokens
    ) {
        this.globalBucket = new TokenBucket(globalTokensPerSecond);
        this.userBuckets = new ConcurrentHashMap<>();
        this.concurrentSemaphore = new Semaphore(maxConcurrentRequests);
        this.maxInputTokens = maxInputTokens;
        this.maxOutputTokens = maxOutputTokens;
    }

    /**
     * 请求准入检查
     */
    public RateLimitResult tryAcquire(String userId, int estimatedTokens) {
        // 1. Token预算硬限制
        if (estimatedTokens > maxInputTokens) {
            return RateLimitResult.denied(
                "Input exceeds max token limit: " + estimatedTokens + " > " + maxInputTokens
            );
        }

        // 2. 并发控制
        if (!concurrentSemaphore.tryAcquire()) {
            return RateLimitResult.denied("Max concurrent requests reached");
        }

        // 3. 全局限流
        if (!globalBucket.tryConsume(1)) {
            concurrentSemaphore.release();
            return RateLimitResult.denied("Global rate limit exceeded");
        }

        // 4. 用户级限流
        var userBucket = userBuckets.computeIfAbsent(
            userId, k -> new TokenBucket(globalBucket.rate / 10)
        );
        if (!userBucket.tryConsume(1 + estimatedTokens / 100)) {
            concurrentSemaphore.release();
            return RateLimitResult.denied("User rate limit exceeded");
        }

        return RateLimitResult.allowed(this::release);
    }

    public void release() {
        concurrentSemaphore.release();
    }

    public long getMaxOutputTokens() {
        return maxOutputTokens;
    }

    public record RateLimitResult(
        boolean allowed,
        String reason,
        Runnable onComplete
    ) {
        public static RateLimitResult allowed(Runnable release) {
            return new RateLimitResult(true, "OK", release);
        }
        public static RateLimitResult denied(String reason) {
            return new RateLimitResult(false, reason, () -> {});
        }
    }

    /**
     * 纯JDK实现的令牌桶
     */
    static class TokenBucket {
        final long rate;
        final double maxTokens;
        double tokens;
        volatile long lastRefill;

        TokenBucket(long tokensPerSecond) {
            this.rate = tokensPerSecond;
            this.maxTokens = tokensPerSecond;
            this.tokens = tokensPerSecond;
            this.lastRefill = System.nanoTime();
        }

        synchronized boolean tryConsume(double count) {
            refill();
            if (tokens >= count) {
                tokens -= count;
                return true;
            }
            return false;
        }

        private void refill() {
            var now = System.nanoTime();
            var elapsed = (now - lastRefill) / 1_000_000_000.0;
            tokens = Math.min(maxTokens, tokens + elapsed * rate);
            lastRefill = now;
        }
    }
}

// RequestQueueManager.java — 请求队列管理
package com.ai.security.rate;

import java.util.concurrent.atomic.*;
import java.util.concurrent.locks.*;

public class RequestQueueManager {

    private final AtomicInteger queueSize = new AtomicInteger(0);
    private final int maxQueueSize;
    private final long maxWaitMs;

    public RequestQueueManager(int maxQueueSize, long maxWaitMs) {
        this.maxQueueSize = maxQueueSize;
        this.maxWaitMs = maxWaitMs;
    }

    /**
     * 尝试入队，超过队列容量或等待时间则拒绝
     */
    public QueueResult tryEnqueue() {
        var currentSize = queueSize.incrementAndGet();
        if (currentSize > maxQueueSize) {
            queueSize.decrementAndGet();
            return QueueResult.rejected("Queue full: " + currentSize);
        }
        return QueueResult.enqueued(() -> queueSize.decrementAndGet());
    }

    public record QueueResult(boolean success, String message, Runnable onDequeue) {
        public static QueueResult enqueued(Runnable dequeue) {
            return new QueueResult(true, "Enqueued", dequeue);
        }
        public static QueueResult rejected(String reason) {
            return new QueueResult(false, reason, () -> {});
        }
    }
}
