### 5. Supply Chain Vulnerabilities（供应链漏洞）— LLM05

LLM应用的供应链包括模型文件、推理框架、MCP Server、第三方依赖等。每个环节都可能引入漏洞。

```java
// SupplyChainSecurityChecker.java — 供应链安全检查
package com.ai.security.supplychain;

import java.security.*;
import java.security.cert.*;
import java.io.*;
import java.nio.file.*;
import java.util.*;

/**
 * 供应链安全检查器：
 * - 依赖漏洞扫描
 * - 模型文件签名验证
 * - MCP Server来源审计
 * - SBOM生成
 */
public class SupplyChainSecurityChecker {

    /**
     * 验证模型文件的数字签名
     */
    public static class ModelSignatureVerifier {

        private final PublicKey trustedPublicKey;

        public ModelSignatureVerifier(Path publicKeyPath) throws Exception {
            var keyFactory = KeyFactory.getInstance("RSA");
            var publicKeyBytes = Files.readAllBytes(publicKeyPath);
            var keySpec = new java.security.spec.X509EncodedKeySpec(publicKeyBytes);
            this.trustedPublicKey = keyFactory.generatePublic(keySpec);
        }

        public VerificationResult verifyModel(Path modelFile, Path signatureFile) {
            try {
                var signature = Signature.getInstance("SHA256withRSA");
                signature.initVerify(trustedPublicKey);
                signature.update(Files.readAllBytes(modelFile));
                var sigBytes = Files.readAllBytes(signatureFile);
                var valid = signature.verify(sigBytes);
                return new VerificationResult(
                    valid,
                    valid ? "Signature verified" : "Signature verification FAILED",
                    modelFile.toString()
                );
            } catch (Exception e) {
                return new VerificationResult(false,
                    "Verification error: " + e.getMessage(), modelFile.toString());
            }
        }

        public record VerificationResult(
            boolean valid,
            String message,
            String modelPath
        ) {}
    }

    /**
     * MCP Server来源审计
     */
    public static class MCPServerAuditor {

        private final Set<String> allowedServerOrigins;

        public MCPServerAuditor(Set<String> allowedOrigins) {
            this.allowedServerOrigins = Set.copyOf(allowedOrigins);
        }

        public AuditReport auditServer(MCPServerInfo server) {
            var findings = new ArrayList<String>();
            var risk = "low";

            // 检查来源
            if (!allowedServerOrigins.contains(server.origin())) {
                findings.add("Unknown origin: " + server.origin());
                risk = "high";
            }

            // 检查是否有认证
            if (server.authType() == null || server.authType().isBlank()) {
                findings.add("No authentication configured");
                risk = risk.equals("high") ? "high" : "medium";
            }

            // 检查权限声明
            var requiredPermissions = server.requiredPermissions();
            if (requiredPermissions.contains("ALL") || requiredPermissions.contains("*")) {
                findings.add("Server requests wildcard permissions");
                risk = "critical";
            }

            // 检查版本
            if (server.version() == null || server.version().contains("SNAPSHOT")) {
                findings.add("Using non-stable version: " + server.version());
                risk = risk.equals("high") ? "high" : "medium";
            }

            return new AuditReport(server.name(), risk, findings);
        }

        public record MCPServerInfo(
            String name,
            String origin,
            String version,
            String authType,
            Set<String> requiredPermissions
        ) {}

        public record AuditReport(
            String serverName,
            String riskLevel,
            List<String> findings
        ) {}
    }

    /**
     * SBOM生成器（简化版CycloneDX格式）
     */
    public static class SBOMGenerator {

        public String generateSBOM(String componentName, String version,
                                    List<DependencyInfo> dependencies) {
            var sb = new StringBuilder();
            sb.append("""
                {
                  "bomFormat": "CycloneDX",
                  "specVersion": "1.6",
                  "version": 1,
                  "metadata": {
                    "component": {
                      "type": "application",
                      "name": "%s",
                      "version": "%s"
                    }
                  },
                  "components": [
                """.formatted(componentName, version));

            var it = dependencies.iterator();
            while (it.hasNext()) {
                var dep = it.next();
                sb.append("""  
                    {
                      "type": "library",
                      "name": "%s",
                      "version": "%s",
                      "purl": "pkg:maven/%s/%s@%s"
                    }%s
                """.formatted(
                    dep.name(), dep.version(),
                    dep.groupId(), dep.artifactId(), dep.version(),
                    it.hasNext() ? "," : ""
                ));
            }

            sb.append("""
                  ]
                }
                """);
            return sb.toString();
        }

        public record DependencyInfo(
            String groupId,
            String artifactId,
            String name,
            String version
        ) {}
    }
}
