### 7. Insecure Plugin Design（不安全插件设计）— LLM07

Agent通过Tool/Plugin扩展能力，但不安全的Tool设计可能导致注入、权限提升或资源滥用。

```java
// SecureToolWrapper.java — Tool安全包装器
package com.ai.security.tool;

import com.networknt.schema.*;
import com.fasterxml.jackson.databind.*;

import java.util.*;
import java.util.concurrent.*;

/**
 * Tool安全包装器：对每个Tool调用进行
 * 1. JSON Schema参数校验
 * 2. 输入范围约束
 * 3. 权限检查
 * 4. 沙箱隔离
 */
public class SecureToolWrapper {

    private final ObjectMapper objectMapper;
    private final Map<String, ToolSecurityConfig> toolConfigs;
    private final Set<String> toolWhitelist;

    public SecureToolWrapper(Set<String> allowedTools) {
        this.objectMapper = new ObjectMapper();
        this.toolConfigs = new ConcurrentHashMap<>();
        this.toolWhitelist = Set.copyOf(allowedTools);
    }

    /**
     * 注册Tool的安全配置
     */
    public void registerTool(String toolName, String jsonSchema,
                              ToolSecurityConfig config) {
        if (!toolWhitelist.contains(toolName)) {
            throw new SecurityException("Tool not in whitelist: " + toolName);
        }
        toolConfigs.put(toolName, config);
    }

    /**
     * 安全执行Tool调用
     */
    public ToolExecutionResult executeSecurely(
        String toolName,
        String parameters,
        ToolExecutor executor
    ) {
        // 1. 工具白名单校验
        if (!toolWhitelist.contains(toolName)) {
            return ToolExecutionResult.blocked("Tool not whitelisted: " + toolName);
        }

        var config = toolConfigs.get(toolName);
        if (config == null) {
            return ToolExecutionResult.blocked("No security config for tool: " + toolName);
        }

        try {
            var jsonNode = objectMapper.readTree(parameters);

            // 2. JSON Schema校验
            var schemaResult = validateAgainstSchema(toolName, jsonNode);
            if (!schemaResult.valid()) {
                return ToolExecutionResult.blocked(
                    "Schema validation failed: " + schemaResult.errors()
                );
            }

            // 3. 输入范围约束检查
            var rangeCheck = checkInputConstraints(toolName, jsonNode, config);
            if (!rangeCheck.valid()) {
                return ToolExecutionResult.blocked(
                    "Input constraint violation: " + rangeCheck.reason()
                );
            }

            // 4. 权限检查
            if (!config.allowedOperations().contains("*")) {
                // 检查具体操作是否在允许列表中
                var operation = extractOperation(toolName, jsonNode);
                if (!config.allowedOperations().contains(operation)) {
                    return ToolExecutionResult.blocked(
                        "Operation not allowed: " + operation
                    );
                }
            }

            // 5. 沙箱执行
            try (var sandbox = new SandboxedExecutor(config.timeoutSeconds())) {
                var result = sandbox.execute(() -> executor.execute(parameters));
                if (result.timedOut()) {
                    return ToolExecutionResult.blocked(
                        "Tool execution timeout after " + config.timeoutSeconds() + "s"
                    );
                }
                return ToolExecutionResult.success(result.output());
            }

        } catch (Exception e) {
            return ToolExecutionResult.blocked(
                "Tool execution error: " + e.getMessage()
            );
        }
    }

    private SchemaValidationResult validateAgainstSchema(
        String toolName, com.fasterxml.jackson.databind.JsonNode params) {
        // 使用NetworkNT JSON Schema Validator
        var schemaPath = toolConfigs.get(toolName).schemaPath();
        var factory = JsonSchemaFactory.getInstance(
            SpecVersion.VersionFlag.V202012
        );
        try {
            var schema = factory.getSchema(
                new java.io.FileInputStream(schemaPath)
            );
            var errors = schema.validate(params);
            return new SchemaValidationResult(
                errors.isEmpty(),
                errors.stream()
                    .map(e -> e.getMessage())
                    .toList()
            );
        } catch (Exception e) {
            return new SchemaValidationResult(false,
                List.of("Schema loading error: " + e.getMessage()));
        }
    }

    private ConstraintCheckResult checkInputConstraints(
        String toolName,
        com.fasterxml.jackson.databind.JsonNode params,
        ToolSecurityConfig config
    ) {
        // 检查数值范围
        for (var field : config.numericConstraints().keySet()) {
            var node = params.get(field);
            if (node != null && node.isNumber()) {
                var value = node.asDouble();
                var constraint = config.numericConstraints().get(field);
                if (value < constraint.min() || value > constraint.max()) {
                    return ConstraintCheckResult.invalid(
                        "Field '%s' value %f out of range [%f, %f]"
                            .formatted(field, value, constraint.min(), constraint.max())
                    );
                }
            }
        }

        // 检查字符串长度
        for (var field : config.stringConstraints().keySet()) {
            var node = params.get(field);
            if (node != null && node.isTextual()) {
                var value = node.asText();
                var constraint = config.stringConstraints().get(field);
                if (value.length() < constraint.min()
                    || value.length() > constraint.max()) {
                    return ConstraintCheckResult.invalid(
                        "Field '%s' length %d out of range [%d, %d]"
                            .formatted(field, value.length(),
                                constraint.min(), constraint.max())
                    );
                }
            }
        }

        return ConstraintCheckResult.valid();
    }

    private String extractOperation(String toolName,
                                     com.fasterxml.jackson.databind.JsonNode params) {
        var opNode = params.get("operation");
        return opNode != null ? opNode.asText() : "default";
    }

    @FunctionalInterface
    public interface ToolExecutor {
        String execute(String parameters) throws Exception;
    }

    public record ToolSecurityConfig(
        String schemaPath,
        Set<String> allowedOperations,
        Map<String, NumericConstraint> numericConstraints,
        Map<String, StringConstraint> stringConstraints,
        long timeoutSeconds
    ) {}

    public record NumericConstraint(double min, double max) {}
    public record StringConstraint(int min, int max) {}

    public record SchemaValidationResult(boolean valid, List<String> errors) {}
    public record ConstraintCheckResult(boolean valid, String reason) {
        public static ConstraintCheckResult valid() {
            return new ConstraintCheckResult(true, "OK");
        }
        public static ConstraintCheckResult invalid(String reason) {
            return new ConstraintCheckResult(false, reason);
        }
    }

    public record ToolExecutionResult(
        boolean success,
        String output,
        String blockReason
    ) {
        public static ToolExecutionResult success(String output) {
            return new ToolExecutionResult(true, output, null);
        }
        public static ToolExecutionResult blocked(String reason) {
            return new ToolExecutionResult(false, null, reason);
        }
    }
}

// SandboxedExecutor.java — 沙箱执行器
class SandboxedExecutor implements AutoCloseable {
    private final ExecutorService executor;
    private final long timeoutSeconds;

    SandboxedExecutor(long timeoutSeconds) {
        this.timeoutSeconds = timeoutSeconds;
        this.executor = Executors.newVirtualThreadPerTaskExecutor();
    }

    SandboxResult execute(java.util.concurrent.Callable<String> task) {
        try {
            var future = executor.submit(task);
            var result = future.get(timeoutSeconds, TimeUnit.SECONDS);
            return new SandboxResult(result, false);
        } catch (TimeoutException e) {
            return new SandboxResult(null, true);
        } catch (Exception e) {
            return new SandboxResult("Error: " + e.getMessage(), false);
        }
    }

    @Override
    public void close() {
        executor.close();
    }

    record SandboxResult(String output, boolean timedOut) {}
}
