### 8. Excessive Agency（过度代理）— LLM08

Agent被授予过多权限后，可能因误判或恶意利用而执行危险操作。应遵循最小权限原则。

```java
// PermissionControlSystem.java — 权限控制系统
package com.ai.security.agency;

import java.util.*;
import java.util.concurrent.*;

/**
 * 最小权限原则实现：每个Agent/Tool仅被授予完成其任务所需的最小权限集
 */
public class PermissionControlSystem {

    // Agent权限矩阵: agentId -> 允许的权限集合
    private final Map<String, Set<Permission>> agentPermissions;

    // Tool能力矩阵: toolName -> 能力描述与风险等级
    private final Map<String, ToolCapability> toolCapabilities;

    // Human-in-the-loop配置: 哪些操作需要人工确认
    private final Set<String> requiresHumanApproval;

    public PermissionControlSystem() {
        this.agentPermissions = new ConcurrentHashMap<>();
        this.toolCapabilities = new ConcurrentHashMap<>();
        this.requiresHumanApproval = Set.of(
            "DELETE", "DROP", "EXECUTE_COMMAND",
            "SEND_EMAIL", "TRANSFER_FUNDS", "DEPLOY"
        );
    }

    /**
     * 在Agent执行操作前，检查权限
     */
    public AuthorizationResult authorize(
        String agentId,
        String operation,
        Map<String, Object> context
    ) {
        // 1. 检查Agent是否被授予该操作权限
        var permissions = agentPermissions.get(agentId);
        if (permissions == null || permissions.isEmpty()) {
            return AuthorizationResult.denied(
                "Agent '%s' has no permissions assigned".formatted(agentId)
            );
        }

        var requiredPermission = Permission.fromOperation(operation);
        if (!permissions.contains(requiredPermission)) {
            return AuthorizationResult.denied(
                "Agent '%s' lacks permission '%s'".formatted(
                    agentId, requiredPermission
                )
            );
        }

        // 2. 检查Tool能力边界
        var toolName = (String) context.getOrDefault("toolName", "");
        var capability = toolCapabilities.get(toolName);
        if (capability != null && !capability.allowedOperations().contains(operation)) {
            return AuthorizationResult.denied(
                "Tool '%s' does not support operation '%s'".formatted(
                    toolName, operation
                )
            );
        }

        // 3. 检查是否需要人工确认
        if (requiresHumanApproval.contains(operation.toUpperCase())) {
            if (!Boolean.TRUE.equals(context.getOrDefault("humanApproved", false))) {
                return AuthorizationResult.requiresApproval(
                    "Operation '%s' requires human approval".formatted(operation),
                    operation,
                    context
                );
            }
        }

        return AuthorizationResult.approved();
    }

    /**
     * 注册Agent权限（最小权限分配）
     */
    public void assignPermissions(String agentId, Set<Permission> permissions) {
        agentPermissions.put(agentId, Set.copyOf(permissions));
    }

    /**
     * 注册Tool能力边界
     */
    public void registerToolCapability(
        String toolName,
        Set<String> allowedOperations,
        String riskLevel,
        String description
    ) {
        toolCapabilities.put(
            toolName,
            new ToolCapability(toolName, allowedOperations, riskLevel, description)
        );
    }

    /**
     * 生成能力矩阵报告
     */
    public String generateCapabilityMatrix() {
        var sb = new StringBuilder();
        sb.append("=== Agent-Tool Capability Matrix ===\n");
        for (var entry : agentPermissions.entrySet()) {
            sb.append("Agent: ").append(entry.getKey()).append("\n");
            sb.append("  Permissions: ").append(entry.getValue()).append("\n");
            sb.append("  Accessible Tools:\n");
            for (var tool : toolCapabilities.entrySet()) {
                var ops = tool.getValue().allowedOperations();
                var hasAccess = entry.getValue().stream()
                    .anyMatch(p -> ops.contains(p.operationName()));
                if (hasAccess) {
                    sb.append("    - ").append(tool.getKey())
                        .append(" [risk: ").append(tool.getValue().riskLevel())
                        .append("]\n");
                }
            }
            sb.append("\n");
        }
        return sb.toString();
    }

    // 内部类型
    public record Permission(String resource, String operationName) {
        public static Permission fromOperation(String operation) {
            var parts = operation.split(":", 2);
            return new Permission(
                parts.length > 1 ? parts[0] : "*",
                parts.length > 1 ? parts[1] : operation
            );
        }
        @Override
        public String toString() {
            return resource + ":" + operationName;
        }
    }

    public record ToolCapability(
        String toolName,
        Set<String> allowedOperations,
        String riskLevel,
        String description
    ) {}

    public record AuthorizationResult(
        boolean approved,
        boolean requiresApproval,
        String message,
        String pendingOperation,
        Map<String, Object> pendingContext
    ) {
        public static AuthorizationResult approved() {
            return new AuthorizationResult(true, false, "Approved", null, null);
        }
        public static AuthorizationResult denied(String reason) {
            return new AuthorizationResult(false, false, reason, null, null);
        }
        public static AuthorizationResult requiresApproval(
            String message, String operation, Map<String, Object> context) {
            return new AuthorizationResult(false, true, message, operation, context);
        }
    }
}
