### 9. Overreliance（过度依赖）— LLM09

过度依赖AI输出而不经验证可能导致错误决策。需要为AI输出添加置信度标记、来源引用和不确定性的明确表达。

```java
// OutputAnnotationService.java — AI输出标注
package com.ai.security.overreliance;

import java.time.*;
import java.util.*;

/**
 * AI输出标注服务：为每个LLM输出添加
 * - 置信度评分
 * - 来源引用
 * - 不确定性标记
 * - 人工审核建议
 */
public class OutputAnnotationService {

    private static final Set<String> UNCERTAINTY_PHRASES = Set.of(
        "可能", "也许", "大概", "或许", "据我所知",
        "建议", "推荐", "考虑", "可以尝试",
        "might", "may", "could", "perhaps", "possibly",
        "I think", "I believe", "as far as I know",
        "it is recommended"
    );

    /**
     * 为AI输出添加完整标注
     */
    public AnnotatedOutput annotate(
        String llmOutput,
        double confidenceScore,
        List<SourceReference> sources,
        boolean requiresHumanReview
    ) {
        // 1. 检测输出中的不确定性表达
        var uncertaintyPhrases = detectUncertainty(llmOutput);
        var hasExplicitUncertainty = !uncertaintyPhrases.isEmpty();

        // 2. 生成置信度标记
        var confidenceLabel = confidenceScore >= 0.9 ? "HIGH"
            : confidenceScore >= 0.7 ? "MEDIUM"
            : "LOW";

        // 3. 构建标注头
        var annotation = buildAnnotation(
            confidenceScore,
            confidenceLabel,
            sources,
            uncertaintyPhrases,
            requiresHumanReview
        );

        // 4. 组合输出
        var annotatedContent = annotation + "\n\n" + llmOutput;

        // 5. 附加元数据
        var metadata = new OutputMetadata(
            confidenceScore,
            confidenceLabel,
            sources,
            uncertaintyPhrases,
            requiresHumanReview,
            Instant.now()
        );

        return new AnnotatedOutput(annotatedContent, metadata);
    }

    private List<String> detectUncertainty(String text) {
        var phrases = new ArrayList<String>();
        var lower = text.toLowerCase();
        for (var phrase : UNCERTAINTY_PHRASES) {
            if (lower.contains(phrase.toLowerCase())) {
                phrases.add(phrase);
            }
        }
        return Collections.unmodifiableList(phrases);
    }

    private String buildAnnotation(
        double confidence,
        String label,
        List<SourceReference> sources,
        List<String> uncertaintyPhrases,
        boolean requiresHumanReview
    ) {
        var sb = new StringBuilder();
        sb.append("[AI-GENERATED CONTENT]\n");
        sb.append("Confidence: %s (%.0f%%)\n".formatted(label, confidence * 100));

        if (!uncertaintyPhrases.isEmpty()) {
            sb.append("Uncertainty markers: ")
                .append(String.join(", ", uncertaintyPhrases))
                .append("\n");
        }

        if (!sources.isEmpty()) {
            sb.append("Sources:\n");
            for (var source : sources) {
                sb.append("  - [").append(source.type()).append("] ")
                    .append(source.title())
                    .append(" (").append(source.url()).append(")\n");
            }
        }

        if (requiresHumanReview) {
            sb.append("\n[REQUIRES HUMAN REVIEW] ");
            sb.append("This output pertains to a critical decision. ");
            sb.append("Please verify before taking action.\n");
        }

        if (confidence < 0.7) {
            sb.append("\n[LOW CONFIDENCE] ");
            sb.append("The model has low confidence in this response. ");
            sb.append("Please independently verify the information.\n");
        }

        return sb.toString();
    }

    // 内部类型
    public record SourceReference(
        String type,
        String title,
        String url
    ) {}

    public record OutputMetadata(
        double confidenceScore,
        String confidenceLabel,
        List<SourceReference> sources,
        List<String> uncertaintyPhrases,
        boolean requiresHumanReview,
        Instant generatedAt
    ) {}

    public record AnnotatedOutput(
        String annotatedContent,
        OutputMetadata metadata
    ) {
        public boolean isHighConfidence() {
            return metadata.confidenceScore() >= 0.9;
        }
        public boolean needsVerification() {
            return metadata.confidenceScore() < 0.7
                || metadata.requiresHumanReview()
                || !metadata.uncertaintyPhrases().isEmpty();
        }
    }
}
