// ApiKeyVaultManager.java — API Key安全存储
package com.ai.security.modeltheft;

import java.util.*;
import java.util.concurrent.*;

/**
 * API Key Vault集成管理器
 * 支持HashiCorp Vault、AWS Secrets Manager等作为后端
 */
public class ApiKeyVaultManager {

    private final Map<String, String> localCache;
    private final VaultBackend vaultBackend;
    private final long cacheTtlMs;

    public ApiKeyVaultManager(VaultBackend backend, long cacheTtlMs) {
        this.localCache = new ConcurrentHashMap<>();
        this.vaultBackend = backend;
        this.cacheTtlMs = cacheTtlMs;
    }

    /**
     * 从Vault获取API Key（不直接暴露明文）
     */
    public String getApiKey(String keyId) {
        return vaultBackend.resolveSecret(keyId);
    }

    /**
     * 轮换API Key
     */
    public void rotateApiKey(String keyId) {
        var newKey = UUID.randomUUID().toString();
        vaultBackend.storeSecret(keyId, newKey);
        localCache.remove(keyId);
    }

