// AnomalyDetectionService.java — 异常访问检测
package com.ai.security.modeltheft;

import java.time.*;
import java.util.concurrent.atomic.*;
import java.util.concurrent.*;

/**
 * 模型盗窃异常检测服务
 * 检测模式：速率异常、时间异常、IP异常、输入模式异常
 */
public class AnomalyDetectionService {

    private final ConcurrentHashMap<String, AccessHistory> accessRecords;
    private final Set<String> blockedIps;

    // 检测阈值
    private static final int MAX_REQUESTS_PER_MINUTE = 200;
    private static final int MAX_REQUESTS_PER_HOUR = 5000;
    private static final double INPUT_SIMILARITY_THRESHOLD = 0.8;

    public AnomalyDetectionService() {
        this.accessRecords = new ConcurrentHashMap<>();
        this.blockedIps = ConcurrentHashMap.newKeySet();
    }

    /**
     * 每次API调用时调用此方法检测异常
     */
    public AnomalyResult detect(String ip, String userId, String inputHash) {
        var history = accessRecords.computeIfAbsent(
            userId, k -> new AccessHistory()
        );

        var now = Instant.now();
        history.record(new AccessRecord(now, ip, inputHash));

        var issues = new ArrayList<String>();

        // 1. IP黑名单检查
        if (blockedIps.contains(ip)) {
            history.markAnomalous();
            return AnomalyResult.blocked("IP in blocklist: " + ip);
        }

        // 2. 速率异常检测
        var ratePerMinute = history.countRecent(Duration.ofMinutes(1));
        if (ratePerMinute > MAX_REQUESTS_PER_MINUTE) {
            issues.add("Rate spike: " + ratePerMinute + " req/min");
            history.markAnomalous();
        }

        var ratePerHour = history.countRecent(Duration.ofHours(1));
        if (ratePerHour > MAX_REQUESTS_PER_HOUR) {
            issues.add("Sustained high rate: " + ratePerHour + " req/hour");
            history.markAnomalous();
        }

        // 3. 时间异常（凌晨高频访问）
        var hour = now.atZone(ZoneId.systemDefault()).getHour();
        if ((hour >= 1 && hour <= 5) && ratePerMinute > 50) {
            issues.add("Unusual access time: " + hour + ":00, rate="
                + ratePerMinute + "/min");
        }

        // 4. 输入模式异常（重复相似请求——疑似模型蒸馏）
        var similarityRatio = history.calculateInputSimilarity(inputHash);
        if (similarityRatio > INPUT_SIMILARITY_THRESHOLD) {
            issues.add("High input similarity: " + String.format("%.2f", similarityRatio)
                + " — possible model distillation");
            history.markAnomalous();
        }

        // 5. 判断是否触发封禁
        if (history.getAnomalyScore() > 80) {
            blockedIps.add(ip);
            return AnomalyResult.blocked(
                "Anomaly threshold exceeded: " + String.join("; ", issues)
            );
        }

        return issues.isEmpty()
            ? AnomalyResult.normal()
            : AnomalyResult.suspicious(String.join("; ", issues));
    }

    // 内部类
    record AccessRecord(Instant timestamp, String ip, String inputHash) {}

    static class AccessHistory {
        private final java.util.Deque<AccessRecord> records = new java.util.ArrayDeque<>();
        private final AtomicInteger anomalyScore = new AtomicInteger(0);

        synchronized void record(AccessRecord record) {
            records.addLast(record);
            // 只保留最近1小时的记录
            var cutoff = Instant.now().minus(Duration.ofHours(1));
            while (!records.isEmpty()
                && records.peekFirst().timestamp().isBefore(cutoff)) {
                records.pollFirst();
            }
        }

        synchronized long countRecent(Duration window) {
            var cutoff = Instant.now().minus(window);
            return records.stream()
                .filter(r -> r.timestamp().isAfter(cutoff))
                .count();
        }

        synchronized double calculateInputSimilarity(String currentHash) {
            // 简化版：检查最近N条记录中相同hash的比例
            var recent = records.stream()
                .skip(Math.max(0, records.size() - 50))
                .toList();
            if (recent.isEmpty()) return 0;
            var same = recent.stream()
                .filter(r -> r.inputHash().equals(currentHash))
                .count();
            return (double) same / recent.size();
        }

        void markAnomalous() {
            anomalyScore.addAndGet(10);
        }

        int getAnomalyScore() {
            return anomalyScore.get();
        }
    }

    public record AnomalyResult(boolean blocked, boolean suspicious, String reason) {
        public static AnomalyResult normal() {
            return new AnomalyResult(false, false, "Normal");
        }
        public static AnomalyResult blocked(String reason) {
            return new AnomalyResult(true, false, reason);
        }
        public static AnomalyResult suspicious(String reason) {
            return new AnomalyResult(false, true, reason);
        }
    }
}
