// SecurityConfig.java
package com.ai.security.config;

import org.springframework.context.annotation.*;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.*;
import org.springframework.security.oauth2.jwt.*;
import org.springframework.security.web.SecurityFilterChain;

@Configuration
@EnableWebSecurity
public class SecurityConfig {

    @Bean
    public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
        http
            .authorizeHttpRequests(authz -> authz
                .requestMatchers("/api/v1/public/**").permitAll()
                .requestMatchers("/api/v1/ai/chat").hasRole("AI_USER")
                .requestMatchers("/api/v1/ai/admin/**").hasRole("AI_ADMIN")
                .requestMatchers("/api/v1/tools/**").hasRole("TOOL_USER")
                .anyRequest().authenticated()
            )
            .oauth2ResourceServer(oauth2 -> oauth2
                .jwt(jwt -> jwt
                    .jwtAuthenticationConverter(new KeycloakJwtConverter())
                )
            );
        return http.build();
    }

    @Bean
    public JwtDecoder jwtDecoder() {
        // Keycloak JWKS端点
        return NimbusJwtDecoder
            .withJwkSetUri("http://localhost:8080/realms/ai-platform/protocol/openid-connect/certs")
            .build();
    }
}

// KeycloakJwtConverter.java
class KeycloakJwtConverter
    implements org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationConverter {

    @Override
    public org.springframework.security.core.Authentication convert(Jwt jwt) {
        var authorities = new java.util.ArrayList<
            org.springframework.security.core.authority.SimpleGrantedAuthority
        >();
        // 从Keycloak JWT提取realm_access.roles
        var realmAccess = (java.util.Map<String, Object>)
            jwt.getClaims().get("realm_access");
        if (realmAccess != null) {
            @SuppressWarnings("unchecked")
            var roles = (java.util.List<String>) realmAccess.get("roles");
            if (roles != null) {
                roles.forEach(role ->
                    authorities.add(
                        new org.springframework.security.core.authority.SimpleGrantedAuthority(
                            "ROLE_" + role.toUpperCase()
                        )
                    )
                );
            }
        }
        return new org.springframework.security.oauth2.server.resource.authentication
            .JwtAuthenticationToken(jwt, authorities);
    }
}
