### OPA/Rego策略即代码集成

```java
// OpaPolicyClient.java
package com.ai.security.policy;

import java.net.http.*;
import java.net.URI;

/**
 * Open Policy Agent (OPA) 集成客户端
 * 通过REST API调用OPA评估Rego策略
 */
public class OpaPolicyClient {

    private final HttpClient httpClient;
    private final String opaBaseUrl;

    public OpaPolicyClient(String opaBaseUrl) {
        this.httpClient = HttpClient.newBuilder()
            .connectTimeout(java.time.Duration.ofSeconds(5))
            .build();
        this.opaBaseUrl = opaBaseUrl;
    }

    /**
     * 评估数据访问策略
     */
    public PolicyResult evaluateDataAccess(
        String userId, String dataCategory, String action
    ) {
        var inputJson = """
            {
              "input": {
                "user_id": "%s",
                "data_category": "%s",
                "action": "%s"
              }
            }
            """.formatted(userId, dataCategory, action);

        return evaluate("data/access_policy", inputJson);
    }

    /**
     * 评估Tool调用策略
     */
    public PolicyResult evaluateToolCall(
        String agentId, String toolName, java.util.Map<String, Object> params
    ) {
        var paramsJson = new com.google.gson.Gson().toJson(params);
        var inputJson = """
            {
              "input": {
                "agent_id": "%s",
                "tool_name": "%s",
                "params": %s
              }
            }
            """.formatted(agentId, toolName, paramsJson);

        return evaluate("tool/call_policy", inputJson);
    }

    private PolicyResult evaluate(String policyPath, String inputJson) {
        try {
            var request = HttpRequest.newBuilder()
                .uri(URI.create(opaBaseUrl + "/v1/data/" + policyPath))
                .header("Content-Type", "application/json")
                .POST(HttpRequest.BodyPublishers.ofString(inputJson))
                .build();

            var response = httpClient.send(
                request, HttpResponse.BodyHandlers.ofString()
            );

            if (response.statusCode() == 200) {
                var body = response.body();
                // 解析OPA返回的JSON: {"result": true/false}
                var gson = new com.google.gson.Gson();
                var result = gson.fromJson(body, java.util.Map.class);
                var allowed = (Boolean) result.get("result");
                return allowed
                    ? PolicyResult.allow()
                    : PolicyResult.deny("Policy denied");
            }

            return PolicyResult.deny(
                "OPA evaluation failed: HTTP " + response.statusCode()
            );
        } catch (Exception e) {
            // 故障安全：策略评估失败时默认拒绝
            return PolicyResult.deny("OPA unavailable: " + e.getMessage());
        }
    }

    public record PolicyResult(boolean allowed, String reason) {
        public static PolicyResult allow() {
            return new PolicyResult(true, "Allowed by policy");
        }
        public static PolicyResult deny(String reason) {
            return new PolicyResult(false, reason);
        }
    }
}
