## 安全审计系统

```java
// AuditLogger.java — AI操作审计日志
package com.ai.security.audit;

import java.time.*;
import java.util.concurrent.*;

/**
 * 完整的AI操作审计日志系统
 * 记录每个请求-响应的安全事件标记，支持重放分析
 */
public class AuditLogger {

    private final java.util.Deque<AuditEntry> recentEntries;
    private final int maxRecentEntries;

    public AuditLogger(int maxRecentEntries) {
        this.recentEntries = new java.util.concurrent.ConcurrentLinkedDeque<>();
        this.maxRecentEntries = maxRecentEntries;
    }

    /**
     * 记录一次完整的AI交互审计事件
     */
    public void logInteraction(AuditContext context) {
        var entry = new AuditEntry(
            UUID.randomUUID().toString(),
            context.userId(),
            context.sessionId(),
            context.llmModel(),
            context.originalPrompt(),
            context.sanitizedPrompt(),
            context.llmResponse(),
            context.securityEvents(),
            context.toolCalls(),
            context.durationMs(),
            context.tokenUsage(),
            Instant.now()
        );

        // 保留在内存队列（可配置持久化到ES/OpenSearch）
        recentEntries.addLast(entry);
        while (recentEntries.size() > maxRecentEntries) {
            recentEntries.pollFirst();
        }

        // 结构化日志输出
        System.Logger logger = System.getLogger("AI-AUDIT");
        logger.log(System.Logger.Level.INFO,
            "[AI-AUDIT] user={0} model={1} tokens={2} duration={3}ms events={4}",
            context.userId(), context.llmModel(),
            context.tokenUsage(), context.durationMs(),
            context.securityEvents().size()
        );
    }

    /**
     * 重放分析：查询特定用户/时间段的安全事件
     */
    public List<AuditEntry> query(String userId, Duration window) {
        var cutoff = Instant.now().minus(window);
        return recentEntries.stream()
            .filter(e -> e.userId().equals(userId)
                && e.timestamp().isAfter(cutoff))
            .toList();
    }

    /**
     * 安全事件统计
     */
    public SecurityStats computeStats(Duration window) {
        var entries = recentEntries.stream()
            .filter(e -> e.timestamp().isAfter(Instant.now().minus(window)))
            .toList();

        var totalRequests = entries.size();
        var blockedRequests = entries.stream()
            .filter(e -> e.securityEvents().contains("BLOCKED"))
            .count();
        var injectionAttempts = entries.stream()
            .filter(e -> e.securityEvents().stream()
                .anyMatch(s -> s.startsWith("INJECTION")))
            .count();
        var piiDetections = entries.stream()
            .filter(e -> e.securityEvents().stream()
                .anyMatch(s -> s.startsWith("PII_DETECTED")))
            .count();

        return new SecurityStats(
            totalRequests,
            blockedRequests,
            injectionAttempts,
            piiDetections
        );
    }

    // 记录类型
    public record AuditEntry(
        String eventId,
        String userId,
        String sessionId,
        String llmModel,
        String originalPrompt,
        String sanitizedPrompt,
        String llmResponse,
        List<String> securityEvents,
        List<String> toolCalls,
        long durationMs,
        int tokenUsage,
        Instant timestamp
    ) {}

    public record AuditContext(
        String userId,
        String sessionId,
        String llmModel,
        String originalPrompt,
        String sanitizedPrompt,
        String llmResponse,
        List<String> securityEvents,
        List<String> toolCalls,
        long durationMs,
        int tokenUsage
    ) {}

    public record SecurityStats(
        long totalRequests,
        long blockedRequests,
        long injectionAttempts,
        long piiDetections
    ) {
        public double blockRate() {
            return totalRequests > 0
                ? (double) blockedRequests / totalRequests * 100 : 0;
        }
        public double injectionRate() {
            return totalRequests > 0
                ? (double) injectionAttempts / totalRequests * 100 : 0;
        }
    }

    // 简单的UUID工具
    private static class UUID {
        static String randomUUID() {
            return java.util.UUID.randomUUID().toString();
        }
    }
}
