## 完整实现：SecurityAdvisorChain

以下是一个完整的、可运行的Spring Boot应用中的SecurityAdvisorChain，按顺序执行各个安全Advisor。

```java
// SecurityAdvisorChain.java — AI安全中间件核心
package com.ai.security.chain;

import com.ai.security.prompt.*;
import com.ai.security.output.*;
import com.ai.security.sensitive.*;
import com.ai.security.agency.*;
import com.ai.security.audit.*;
import com.ai.security.modeltheft.*;
import com.ai.security.rate.*;

import java.util.*;
import java.util.concurrent.*;

/**
 * SecurityAdvisorChain — 可插拔的AI安全中间件
 * 
 * 执行顺序（与Spring AI的Advisor机制对齐）：
 * 1. InputSanitizationAdvisor — 输入清洗
 * 2. PromptInjectionDetectionAdvisor — 注入检测
 * 3. SensitiveDataMaskingAdvisor — 敏感数据脱敏
 * 4. ToolPermissionCheckAdvisor — 工具权限检查
 * 5. OutputSanitizationAdvisor — 输出清洗
 * 6. AuditLoggingAdvisor — 审计日志
 * 
 * 每个Advisor独立可插拔，通过配置启用或禁用
 */
public class SecurityAdvisorChain {

    private final List<SecurityAdvisor> advisors;
    private final AuditLogger auditLogger;

    public SecurityAdvisorChain(SecurityConfig config) {
        var chain = new ArrayList<SecurityAdvisor>();

        // 按顺序注册Advisor（仅注册已启用的）
        if (config.inputSanitizationEnabled()) {
            chain.add(new InputSanitizationAdvisor(
                new PromptSecurityWrapper()
            ));
        }
        if (config.injectionDetectionEnabled()) {
            chain.add(new PromptInjectionDetectionAdvisor(
                new PromptSecurityWrapper(),
                config.injectionBlockThreshold()
            ));
        }
        if (config.sensitiveDataMaskingEnabled()) {
            chain.add(new SensitiveDataMaskingAdvisor(
                new SensitiveDataMasker()
            ));
        }
        if (config.toolPermissionCheckEnabled()) {
            chain.add(new ToolPermissionCheckAdvisor(
                new PermissionControlSystem()
            ));
        }
        if (config.outputSanitizationEnabled()) {
            chain.add(new OutputSanitizationAdvisor(
                new OutputSecurityFilter(Set.of("offensive_term_1", "offensive_term_2"))
            ));
        }
        if (config.auditLoggingEnabled()) {
            chain.add(new AuditLoggingAdvisor(
                new AuditLogger(10_000)
            ));
        }

        this.advisors = List.copyOf(chain);
        this.auditLogger = new AuditLogger(10_000);
    }

    /**
     * 执行完整的安全管道
     */
    public ChainResult execute(SecurityContext context) {
        var securityEvents = new ArrayList<String>();

        for (var advisor : advisors) {
            var result = advisor.evaluate(context);
            context = result.updatedContext();

            if (!result.passed()) {
                securityEvents.add(advisor.name() + ": BLOCKED — " + result.reason());
                var auditCtx = context.toAuditContext(securityEvents);
                auditLogger.logInteraction(auditCtx);
                return ChainResult.blocked(
                    securityEvents,
                    result.reason(),
                    auditor -> ()
                );
            }

            if (!result.warnings().isEmpty()) {
                securityEvents.addAll(result.warnings().stream()
                    .map(w -> advisor.name() + ": WARN — " + w)
                    .toList()
                );
            }
        }

        var auditCtx = context.toAuditContext(securityEvents);
        auditLogger.logInteraction(auditCtx);
        return ChainResult.passed(context, securityEvents);
    }

    // ======== Advisor接口 ========

    @FunctionalInterface
    public interface SecurityAdvisor {
        AdvisorResult evaluate(SecurityContext context);
        default String name() { return this.getClass().getSimpleName(); }
    }

    public record AdvisorResult(
        boolean passed,
        String reason,
        List<String> warnings,
        SecurityContext updatedContext
    ) {
        public static AdvisorResult pass(SecurityContext ctx) {
            return new AdvisorResult(true, "OK", List.of(), ctx);
        }
        public static AdvisorResult passWithWarnings(
            SecurityContext ctx, List<String> warnings) {
            return new AdvisorResult(true, "OK", warnings, ctx);
        }
        public static AdvisorResult block(SecurityContext ctx, String reason) {
            return new AdvisorResult(false, reason, List.of(), ctx);
        }
    }

    // ======== 1. InputSanitizationAdvisor ========

    static class InputSanitizationAdvisor implements SecurityAdvisor {
        private final PromptSecurityWrapper wrapper;

        InputSanitizationAdvisor(PromptSecurityWrapper wrapper) {
            this.wrapper = wrapper;
        }

        @Override
        public AdvisorResult evaluate(SecurityContext ctx) {
            var rawInput = ctx.userInput();
            var wrappedInput = wrapper.wrapUserInput(rawInput);
            var risk = wrapper.assessRisk(rawInput);

            if (risk.isSevere()) {
                return AdvisorResult.block(ctx,
                    "Input sanitization detected severe risk: " + risk.reasons());
            }

            var updatedCtx = ctx.withSanitizedInput(wrappedInput);
            if (risk.isSuspicious()) {
                return AdvisorResult.passWithWarnings(updatedCtx,
                    List.of("Suspicious input patterns: " + risk.reasons()));
            }
            return AdvisorResult.pass(updatedCtx);
        }
    }

    // ======== 2. PromptInjectionDetectionAdvisor ========

    static class PromptInjectionDetectionAdvisor implements SecurityAdvisor {
        private final PromptSecurityWrapper wrapper;
        private final int blockThreshold;

        PromptInjectionDetectionAdvisor(PromptSecurityWrapper wrapper,
                                         int blockThreshold) {
            this.wrapper = wrapper;
            this.blockThreshold = blockThreshold;
        }

        @Override
        public AdvisorResult evaluate(SecurityContext ctx) {
            var risk = wrapper.assessRisk(ctx.userInput());

            if (risk.score() >= blockThreshold) {
                ctx.addSecurityEvent("INJECTION_BLOCKED");
                return AdvisorResult.block(ctx,
                    "Prompt injection detected: score=" + risk.score()
                    + ", reasons=" + risk.reasons());
            }
            return AdvisorResult.pass(ctx);
        }
    }

    // ======== 3. SensitiveDataMaskingAdvisor ========

    static class SensitiveDataMaskingAdvisor implements SecurityAdvisor {
        private final SensitiveDataMasker masker;

        SensitiveDataMaskingAdvisor(SensitiveDataMasker masker) {
            this.masker = masker;
        }

        @Override
        public AdvisorResult evaluate(SecurityContext ctx) {
            // 对用户输入进行PII检测
            var inputResult = masker.mask(ctx.userInput());
            var updatedCtx = ctx.withSanitizedInput(inputResult.maskedText());

            var warnings = new ArrayList<String>();
            if (inputResult.hadDetections()) {
                warnings.add("PII_DETECTED in input: "
                    + inputResult.detectedTypes());
                updatedCtx.addSecurityEvent(
                    "PII_DETECTED:" + String.join(",", inputResult.detectedTypes())
                );
            }

            // 如果已经有LLM响应，也检查响应
            if (ctx.llmResponse() != null) {
                var outputResult = masker.mask(ctx.llmResponse());
                if (outputResult.hadDetections()) {
                    warns.add("PII_DETECTED in output: "
                        + outputResult.detectedTypes());
                    updatedCtx = updatedCtx.withResponse(outputResult.maskedText());
                    updatedCtx.addSecurityEvent(
                        "PII_DETECTED_OUTPUT:"
                        + String.join(",", outputResult.detectedTypes())
                    );
                }
            }

            return warnings.isEmpty()
                ? AdvisorResult.pass(updatedCtx)
                : AdvisorResult.passWithWarnings(updatedCtx, warnings);
        }
    }

    // ======== 4. ToolPermissionCheckAdvisor ========

    static class ToolPermissionCheckAdvisor implements SecurityAdvisor {
        private final PermissionControlSystem pcs;

        ToolPermissionCheckAdvisor(PermissionControlSystem pcs) {
            this.pcs = pcs;
        }

        @Override
        public AdvisorResult evaluate(SecurityContext ctx) {
            var toolCalls = ctx.toolCalls();
            if (toolCalls == null || toolCalls.isEmpty()) {
                return AdvisorResult.pass(ctx); // 没有Tool调用，直接通过
            }

            for (var toolCall : toolCalls) {
                var authResult = pcs.authorize(
                    ctx.agentId(),
                    toolCall.operation(),
                    java.util.Map.of("toolName", toolCall.toolName())
                );

                if (!authResult.approved()) {
                    ctx.addSecurityEvent(
                        "TOOL_PERMISSION_DENIED:" + toolCall.toolName()
                    );
                    return AdvisorResult.block(ctx, authResult.message());
                }

                if (authResult.requiresApproval()) {
                    ctx.addSecurityEvent(
                        "TOOL_NEEDS_APPROVAL:" + toolCall.toolName()
                    );
                    return AdvisorResult.block(ctx,
                        "Tool '" + toolCall.toolName()
                        + "' requires human approval");
                }
            }

            return AdvisorResult.pass(ctx);
        }
    }

    // ======== 5. OutputSanitizationAdvisor ========

    static class OutputSanitizationAdvisor implements SecurityAdvisor {
        private final OutputSecurityFilter filter;

        OutputSanitizationAdvisor(OutputSecurityFilter filter) {
            this.filter = filter;
        }

        @Override
        public AdvisorResult evaluate(SecurityContext ctx) {
            if (ctx.llmResponse() == null) {
                return AdvisorResult.pass(ctx); // 还没有输出，先通过
            }

            var auditResult = filter.audit(ctx.llmResponse());

            if (!auditResult.isSafe() && auditResult.riskLevel().equals("critical")) {
                ctx.addSecurityEvent("OUTPUT_BLOCKED_CRITICAL");
                return AdvisorResult.block(
                    ctx,
                    "Output blocked due to critical security risks: "
                    + auditResult.issues()
                );
            }

            var updatedCtx = ctx.withResponse(auditResult.sanitizedOutput());
            if (!auditResult.issues().isEmpty()) {
                return AdvisorResult.passWithWarnings(updatedCtx, auditResult.issues());
            }
            return AdvisorResult.pass(updatedCtx);
        }
    }

    // ======== 6. AuditLoggingAdvisor ========

    static class AuditLoggingAdvisor implements SecurityAdvisor {
        private final AuditLogger logger;

        AuditLoggingAdvisor(AuditLogger logger) {
            this.logger = logger;
        }

        @Override
        public AdvisorResult evaluate(SecurityContext ctx) {
            // AuditLogging总是通过，但记录当前状态
            var auditCtx = ctx.toAuditContext(ctx.securityEvents());
            logger.logInteraction(auditCtx);
            return AdvisorResult.pass(ctx);
        }
    }

    // ======== SecurityContext ====

    public static class SecurityContext {
        private final String userId;
        private final String sessionId;
        private final String agentId;
        private final String userInput;
        private String sanitizedInput;
        private String llmResponse;
        private final String llmModel;
        private final List<ToolCallInfo> toolCalls;
        private final List<String> securityEvents;
        private final long startTime;

        private SecurityContext(Builder builder) {
            this.userId = builder.userId;
            this.sessionId = builder.sessionId;
            this.agentId = builder.agentId;
            this.userInput = builder.userInput;
            this.sanitizedInput = builder.userInput;
            this.llmResponse = builder.llmResponse;
            this.llmModel = builder.llmModel;
            this.toolCalls = builder.toolCalls != null
                ? List.copyOf(builder.toolCalls)
                : List.of();
            this.securityEvents = new ArrayList<>();
            this.startTime = System.currentTimeMillis();
        }

        // Getter方法
        public String userId() { return userId; }
        public String sessionId() { return sessionId; }
        public String agentId() { return agentId; }
        public String userInput() { return userInput; }
        public String sanitizedInput() { return sanitizedInput; }
        public String llmResponse() { return llmResponse; }
        public String llmModel() { return llmModel; }
        public List<ToolCallInfo> toolCalls() { return toolCalls; }
        public List<String> securityEvents() {
            return Collections.unmodifiableList(securityEvents);
        }

        // 不可变更新方法
        public SecurityContext withSanitizedInput(String input) {
            var copy = new Builder(this).userInput(this.userInput).build();
            copy.sanitizedInput = input;
            copy.securityEvents.addAll(this.securityEvents);
            return copy;
        }

        public SecurityContext withResponse(String response) {
            var copy = new Builder(this).userInput(this.userInput).build();
            copy.sanitizedInput = this.sanitizedInput;
            copy.llmResponse = response;
            copy.securityEvents.addAll(this.securityEvents);
            return copy;
        }

        public void addSecurityEvent(String event) {
            this.securityEvents.add(event);
        }

        public AuditLogger.AuditContext toAuditContext(List<String> events) {
            return new AuditLogger.AuditContext(
                userId, sessionId, llmModel,
                userInput, sanitizedInput, llmResponse,
                events,
                toolCalls.stream()
                    .map(tc -> tc.toolName() + ":" + tc.operation())
                    .toList(),
                System.currentTimeMillis() - startTime,
                0 // token usage需要在实际调用后填入
            );
        }

        // Builder
        public static class Builder {
            private String userId;
            private String sessionId;
            private String agentId;
            private String userInput;
            private String llmResponse;
            private String llmModel;
            private List<ToolCallInfo> toolCalls;

            public Builder() {}

            public Builder(SecurityContext ctx) {
                this.userId = ctx.userId;
                this.sessionId = ctx.sessionId;
                this.agentId = ctx.agentId;
                this.userInput = ctx.userInput;
                this.llmResponse = ctx.llmResponse;
                this.llmModel = ctx.llmModel;
                this.toolCalls = ctx.toolCalls;
            }

            public Builder userId(String v) { this.userId = v; return this; }
            public Builder sessionId(String v) { this.sessionId = v; return this; }
            public Builder agentId(String v) { this.agentId = v; return this; }
            public Builder userInput(String v) { this.userInput = v; return this; }
            public Builder llmResponse(String v) { this.llmResponse = v; return this; }
            public Builder llmModel(String v) { this.llmModel = v; return this; }
            public Builder toolCalls(List<ToolCallInfo> v) { this.toolCalls = v; return this; }

            public SecurityContext build() {
                return new SecurityContext(this);
            }
        }
    }

    // ======== 辅助类型 ========

    public record ToolCallInfo(String toolName, String operation, String parameters) {}

    public record SecurityConfig(
        boolean inputSanitizationEnabled,
        boolean injectionDetectionEnabled,
        int injectionBlockThreshold,
        boolean sensitiveDataMaskingEnabled,
        boolean toolPermissionCheckEnabled,
        boolean outputSanitizationEnabled,
        boolean auditLoggingEnabled
    ) {
        public static SecurityConfig allEnabled() {
            return new SecurityConfig(true, true, 60, true, true, true, true);
        }
        public static SecurityConfig production() {
            return new SecurityConfig(true, true, 50,
                true, true, true, true);
        }
    }

    public record ChainResult(
        boolean passed,
        SecurityContext context,
        List<String> securityEvents,
        String blockReason,
        java.util.function.Consumer<Runnable> onComplete
    ) {
        public static ChainResult passed(
            SecurityContext ctx, List<String> events) {
            return new ChainResult(true, ctx, events, null,
                callback -> {});
        }
        public static ChainResult blocked(
            List<String> events, String reason,
            java.util.function.Consumer<Runnable> auditCallback) {
            return new ChainResult(false, null, events, reason,
                auditCallback);
        }
    }
}

