@Service
public class SessionReplayService {

    /**
     * 按时间线回放会话的所有步骤。
     */
    public ReplayTimeline replay(String sessionId) {
        var session = sessionRepo.findById(sessionId)
            .orElseThrow();

        var events = new ArrayList<ReplayEvent>();
        var messages = parseMessages(session.messages);

        for (int i = 0; i < messages.size(); i++) {
            var msg = messages.get(i);
            events.add(new ReplayEvent(
                i,
                msg.role(),
                msg.content(),
                msg.toolCalls(),
                msg.timestamp()
            ));
        }

        return new ReplayTimeline(
            session.id(),
            session.agentId(),
            session.userId(),
            events,
            session.totalTokens(),
            session.totalCost(),
            session.createdAt()
        );
    }

    public record ReplayTimeline(
        String sessionId,
        String agentId,
        String userId,
        List<ReplayEvent> events,
        int totalTokens,
        double totalCost,
        Instant startedAt
    ) {}

    public record ReplayEvent(
