        this.displayName = displayName;
    }
}

// PaymentPeriod.java — 缴费期间枚举
enum PaymentPeriod {
    SINGLE("趸交"),
    THREE_YEARS("3年"),
    FIVE_YEARS("5年"),
    TEN_YEARS("10年"),
    TWENTY_YEARS("20年"),
    THIRTY_YEARS("30年"),
    TO_AGE_60("至60周岁"),
    TO_AGE_70("至70周岁");

    private final String displayName;

    PaymentPeriod(String displayName) {
        this.displayName = displayName;
    }
}

// CoveragePeriod.java — 保障期限枚举
enum CoveragePeriod {
    ONE_YEAR("1年"),
    TEN_YEARS("10年"),
    TWENTY_YEARS("20年"),
    TO_AGE_60("至60周岁"),
    TO_AGE_70("至70周岁"),
    LIFETIME("终身");

    private final String displayName;

    CoveragePeriod(String displayName) {
