    ClaimDecision decision,
    BigDecimal payableAmount,
    List<String> reasons,
    String decisionLetter,
    boolean needManualReview
) {
    static ClaimResult materialError(String message) {
        return new ClaimResult(
            ClaimDecision.PENDING_INFO, BigDecimal.ZERO,
            List.of(message), message, false
        );
    }
}

enum ClaimDecision {
    APPROVED, PARTIALLY_APPROVED, REJECTED, PENDING_INFO, REFER_TO_MANUAL
}
