    private final ProductQueryService productQueryService;
    private final ClaimGuideService claimGuideService;

    public InsuranceAgentService(ChatModel chatModel,
                                  PolicyQueryService policyQueryService,
                                  ProductQueryService productQueryService,
                                  ClaimGuideService claimGuideService) {
        this.policyQueryService = policyQueryService;
        this.productQueryService = productQueryService;
        this.claimGuideService = claimGuideService;

        // 构建Agent：注册所有Tool
        this.agentClient = ChatClient.builder(chatModel)
            .defaultSystem("""
                你是一个专业的保险客服助手。你可以帮助用户：
                1. 查询保单信息（保单状态、保障内容、缴费情况）
                2. 解答理赔流程问题（需要什么材料、如何提交）
                3. 解答产品咨询（保障范围、保费、投保条件）
                4. 对于无法处理的问题，引导用户转人工客服

                请用友好、专业的语气回答。涉及具体数字和条款时务必准确。
