            .build();
    }

    /**
     * 客服对话入口
     */
    public AgentResponse chat(String userId, String message) {
        var response = agentClient.prompt()
                .user(message)
                .tools(
                    new PolicyQueryTools(policyQueryService),
                    new ProductQueryTools(productQueryService),
                    new ClaimQueryTools(claimGuideService)
                )
                .call()
                .content();

        return new AgentResponse(response, false);
    }

